window.__PAGES=window.__PAGES||{};window.__PAGES["pages/conversation.html"]="<!-- Conversation Page — ported from conversation-page-redesign.html with all custom features -->\n<style>\n/* Conversation layout — 4-col: sidenav | list | workspace | drawer */\n.conv-layout{display:flex;height:100%;overflow:hidden;position:relative;flex:1;min-height:0}\n\n/* ── Sidenav ── */\n.conv-sidenav{flex:0 0 200px;width:200px;background:var(--card);border-right:1px solid var(--border);display:flex;flex-direction:column;overflow-y:auto;transition:flex-basis .2s cubic-bezier(0.2,0,0,1),width .2s cubic-bezier(0.2,0,0,1)}\n.sn-head{display:flex;align-items:center;justify-content:space-between;padding:11px 12px}\n.sn-title{font-size:14px;font-weight:600}\n.sn-collapse{width:26px;height:26px;border:none;background:none;cursor:pointer;color:var(--muted);border-radius:5px;font-size:15px}\n.sn-collapse:hover{background:var(--border)}\n.sn-group{padding:8px 0}\n.sn-glabel{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);padding:4px 12px 3px;font-weight:600}\n.sn-disc{display:flex;align-items:center;gap:9px;padding:7px 12px;cursor:pointer;font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.04em;width:100%;border:none;background:none;text-align:left;font-family:inherit}\n.sn-disc .chev{margin-left:auto;transition:transform .15s}\n.sn-disc.open .chev{transform:rotate(90deg)}\n.sn-disc .dotind{color:var(--accent);font-size:16px;line-height:1;display:none}\n.sn-group:has(.sn-item.active)>.sn-disc:not(.open) .dotind{display:inline;margin-left:auto}\n.sn-group:has(.sn-item.active)>.sn-disc:not(.open) .chev{margin-left:6px}\n.sn-item{display:flex;align-items:center;gap:9px;padding:7px 12px;cursor:pointer;font-size:13px;position:relative;color:var(--ink)}\n.sn-item:hover{background:var(--border)}\n.sn-item.active{background:color-mix(in srgb,var(--accent) 12%,transparent);font-weight:600}\n.sn-item.active::before{content:\"\";position:absolute;left:0;top:4px;bottom:4px;width:3px;background:var(--accent);border-radius:0 3px 3px 0}\n.sn-item .ic{width:18px;flex:0 0 18px;text-align:center;font-size:14px}\n.sn-item .txt{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sn-item .cnt{font-size:11px;background:var(--border);color:var(--ink);border-radius:9px;padding:0 6px;min-width:18px;text-align:center}\n.sn-item.active .cnt{background:var(--accent);color:#fff}\n.sn-div{height:2px;margin:2px 0}\n.sn-add{margin-left:6px;color:var(--muted);font-size:14px;cursor:pointer;border-radius:4px;padding:0 3px}\n.sn-add:hover{background:var(--border);color:var(--accent)}\n\n/* ── Sidenav collapsed (1280) ── */\n.conv-layout.sidenavCollapsed .conv-sidenav{flex-basis:56px;width:56px}\n.conv-layout.sidenavCollapsed .sn-title,.conv-layout.sidenavCollapsed .txt,\n.conv-layout.sidenavCollapsed .sn-glabel,.conv-layout.sidenavCollapsed .sn-disc .chev,\n.conv-layout.sidenavCollapsed .sn-disc .dotind,.conv-layout.sidenavCollapsed .sn-add,\n.conv-layout.sidenavCollapsed .sn-disc span:not(.ic),.conv-layout.sidenavCollapsed .sn-div{display:none}\n.conv-layout.sidenavCollapsed .sn-sub{padding-left:0}\n.conv-layout.sidenavCollapsed .sn-sub .sn-item{padding-left:0}\n.conv-layout.sidenavCollapsed .sn-item,.conv-layout.sidenavCollapsed .sn-disc{justify-content:center;padding:9px 0}\n.conv-layout.sidenavCollapsed .sn-disc{cursor:default}\n.conv-layout.sidenavCollapsed .sn-group:has(.sn-item.active)>.sn-disc{color:var(--accent)}\n.conv-layout.sidenavCollapsed .sn-item{position:relative}\n.conv-layout.sidenavCollapsed .sn-item .cnt{position:absolute;top:2px;left:50%;margin-left:2px;min-width:14px;height:14px;font-size:9px;line-height:14px;padding:0 3px;box-shadow:0 0 0 1px var(--card)}\n.conv-layout.sidenavCollapsed .sn-item[data-cnt=\"0\"] .cnt{display:none}\n/* Collapsed: only ACTIVE child visible as icon per section (proto lama); peek reveals all */\n.conv-layout.sidenavCollapsed .sn-sub .sn-item:not(.active){display:none}\n/* Peek: collapsed sidenav expands overlaying list */\n.conv-layout.sidenavCollapsed .conv-sidenav.peek{flex-basis:200px;width:200px;margin-right:-144px;box-shadow:2px 0 12px rgba(0,0,0,.18);z-index:30}\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-title,.conv-layout.sidenavCollapsed .conv-sidenav.peek .txt,\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-disc .chev,.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-disc .dotind,\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-add,.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-disc span:not(.ic),\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-div{display:revert}\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-sub .sn-item{display:flex}\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-sub,.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-sub .sn-item{padding-left:8px}\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-sub .sn-item{padding-left:20px}\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-item,.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-disc{justify-content:flex-start;padding:7px 12px}\n.conv-layout.sidenavCollapsed .conv-sidenav.peek .sn-item .cnt{position:static;min-width:18px;height:auto;font-size:11px;line-height:normal;box-shadow:none;margin-left:0}\n\n/* ── Conversation list ── */\n.conv-list{flex:0 0 320px;width:320px;border-right:1px solid var(--border);display:flex;flex-direction:column;background:var(--card);overflow:hidden}\n.list-head{padding:10px 12px}\n.list-search{width:100%;padding:7px 10px;border:1px solid var(--border);border-radius:20px;font-size:12px;background:var(--bg)}\n/* Filter bar — full vs icon mode */\n.fbar{display:flex;align-items:center;gap:6px;padding:6px 12px;flex-wrap:wrap}\n/* Icon mode (1280) */\n.fbar-icon{display:none;align-items:center;gap:8px}\n.fbar-icon .fctrl{width:34px;height:32px;border:1px solid var(--border);border-radius:8px;background:var(--card);cursor:pointer;font-size:13px;display:inline-flex;align-items:center;justify-content:center}\n.fbar-icon .fctrl:hover{border-color:var(--accent)}\n.fbar-icon .fspacer{flex:1}\n.fbar-icon .fico2{width:28px;height:28px}\n/* Full mode (1440) */\n.fbar-exp{display:none;flex-direction:column;gap:8px;width:100%}\n.finbox{display:flex;align-items:center}\n.fsearchbar{display:flex;align-items:center;gap:6px;cursor:pointer;padding:4px 0;font-size:14px;font-weight:600}\n.fsearchbar .si{font-size:14px}\n.frow2{display:flex;align-items:center;gap:8px}\n.seg-status{display:flex;gap:4px;padding:4px;border-radius:10px;background:#f1f5f9;border:1px solid var(--border)}\n.seg{display:inline-flex;align-items:center;gap:4px;height:24px;padding:0 12px;border:none;border-radius:8px;background:transparent;color:var(--ink);font-weight:500;font-size:12px;cursor:pointer}\n.seg.active{background:#fff;box-shadow:0 2px 8px rgba(0,0,0,.08)}\n.seg .segcnt{min-width:auto;height:16px;padding:0 5px;font-size:10px;border-radius:8px;background:var(--border);color:var(--ink);display:inline-flex;align-items:center}\n.seg.active .segcnt{background:var(--accent);color:#fff}\n.fctrl-lbl{height:28px;padding:0 10px;border:1px solid var(--border);border-radius:8px;background:var(--card);cursor:pointer;font-size:12px;display:inline-flex;align-items:center;gap:4px}\n.fchips{display:flex;align-items:center;gap:4px}\n.fchip{border:1px solid var(--border);border-radius:999px;padding:0 12px;height:24px;font-size:12px;background:var(--card);color:var(--ink);cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center}\n.fchip:hover:not(.on){border-color:var(--accent)}\n.fchip.on{background:#eaf1ff;border-color:#2563eb;color:#2563eb;font-weight:600}\n.fchip.ico{width:24px;height:24px;padding:0;border-radius:999px;justify-content:center}\n.fspacer{flex:1}\n.ficons{display:flex;gap:4px}\n/* Filter dropdown menus */\n.fmenu{position:absolute;top:100%;left:0;background:var(--card);border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 12px rgba(0,0,0,.12);z-index:50;min-width:180px;padding:4px 0}\n.fmenu.hide{display:none}\n.fitem{display:flex;align-items:center;gap:8px;padding:8px 12px;width:100%;border:none;background:none;cursor:pointer;font-size:13px;text-align:left}\n.fitem:hover{background:var(--bg)}\n.fitem .fcheck{margin-left:auto;visibility:hidden}\n.fitem.active .fcheck{visibility:visible}\n.fitem .fcount{color:var(--muted);font-size:11px}\n/* Toggle classes */\n.conv-layout.filterIcon .fbar-exp{display:none!important}\n.conv-layout.filterIcon .fbar-icon{display:flex!important}\n.conv-layout.filterFull .fbar-icon{display:none!important}\n.conv-layout.filterFull .fbar-exp{display:flex!important}\n.list-body{flex:1;overflow-y:auto}\n.conv-row{display:flex;align-items:center;gap:10px;padding:10px 12px;cursor:pointer;border-bottom:1px solid var(--border);transition:.1s}\n.conv-row:hover{background:var(--bg)}\n.conv-row.sel{background:rgba(79,70,229,.06);border-left:3px solid var(--accent)}\n.conv-row .av{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;color:#fff;flex:0 0 36px}\n.conv-row .body{flex:1;min-width:0}\n.conv-row .name-row{display:flex;align-items:center;gap:4px}\n.conv-row .name{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.conv-row .prev{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px}\n.conv-row .meta{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex:0 0 auto}\n.conv-row .time{font-size:11px;color:var(--muted)}\n.conv-row .unread{background:var(--accent);color:#fff;font-size:10px;font-weight:700;padding:1px 6px;border-radius:10px}\n.conv-row .mention{font-size:10px;background:#dbeafe;color:#2563eb;padding:1px 5px;border-radius:8px;font-weight:600}\n.conv-row .expired-tag{font-size:9px;font-weight:600;padding:1px 6px;border-radius:8px;background:#fef3c7;color:#b45309;border:1px solid #fde68a}\n.conv-row .disc-dot{width:8px;height:8px;border-radius:50%;background:#ef4444;display:inline-block;margin-left:2px;vertical-align:middle}\n.conv-row .av-wrap{position:relative;flex:0 0 36px;width:36px;height:36px}\n.conv-row .bchk{position:absolute;inset:0;margin:0;width:36px;height:36px;cursor:pointer;opacity:0;transition:.1s;-webkit-appearance:none;appearance:none;border-radius:50%}\n.conv-row .bchk:checked{opacity:1;background:var(--accent);border:2px solid var(--accent)}\n.conv-row .bchk:checked::after{content:\"✓\";position:absolute;inset:0;display:grid;place-items:center;color:#fff;font-size:16px;font-weight:700}\n.conv-row:hover .bchk{opacity:1;background:rgba(255,255,255,.85);border:2px solid var(--accent)}\n.conv-row:hover .bchk:checked{background:var(--accent)}\n.conv-row:hover .av,.conv-row .av-wrap:has(.bchk:checked) .av{opacity:.35}\n.bulk-bar{display:none;align-items:center;gap:8px;padding:8px 12px;background:rgba(79,70,229,.08);border-bottom:1px solid var(--border);flex-wrap:wrap}\n.bulk-bar.on{display:flex}\n.bulk-bar .bcount{font-size:12px;font-weight:700;color:var(--accent)}\n.bulk-bar button{font-size:12px;padding:4px 8px;border:1px solid var(--border);border-radius:6px;background:var(--card);cursor:pointer}\n.bulk-bar button:hover{background:var(--bg)}\n.bulk-bar .bdel{color:#dc2626;border-color:#fecaca}\n.bulk-bar .bprimary{background:var(--accent);color:#fff;border-color:var(--accent);font-weight:600}\n.bulk-bar .bprimary:hover{filter:brightness(1.08);background:var(--accent)}\n.bmore-wrap{position:relative}\n.bmore{display:none;position:absolute;top:calc(100% + 4px);left:0;z-index:30;flex-direction:column;gap:4px;min-width:180px;padding:6px;background:var(--card);border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.12)}\n.bmore.on{display:flex}\n.bmore button,.bmore .bsel{width:100%;text-align:left;font-size:12px;padding:6px 8px;border:none;border-radius:6px;background:none;cursor:pointer}\n.bmore button:hover{background:var(--bg)}\n.bmore .bsel{border:1px solid var(--border);background:var(--card)}\n.bmore-sep{height:1px;background:var(--border);margin:2px 0}\n.bulk-bar .bx{margin-left:auto;border:none;background:none;font-size:14px}\n\n/* ── Workspace ── */\n.conv-ws{flex:1;display:flex;flex-direction:column;min-width:0;overflow:hidden}\n.ws-head{background:var(--card);border-bottom:1px solid var(--border);padding:9px 14px;display:flex;align-items:center;gap:10px}\n.ws-head .name{font-weight:600;font-size:14px}\n.ws-head .sub{color:var(--muted);font-size:12px}\n.ws-head .ws-actions{margin-left:auto;display:flex;align-items:center;gap:8px}\n.thread{flex:1;overflow-y:auto;padding:14px 20px;display:flex;flex-direction:column;gap:6px;background:var(--bg)}\n.daysep{text-align:center;font-size:11px;color:var(--muted);padding:8px 0;position:relative}\n.daysep::before{content:'';position:absolute;left:0;right:0;top:50%;border-top:1px solid var(--border);z-index:0}\n.daysep span{position:relative;z-index:1;background:var(--bg);padding:0 10px}\n.bub{max-width:70%;padding:8px 12px;border-radius:12px;font-size:13px;line-height:1.5;position:relative;word-wrap:break-word}\n.bub.in{background:var(--card);border:1px solid var(--border);align-self:flex-start;border-bottom-left-radius:4px}\n.bub.out{background:var(--accent);color:#fff;align-self:flex-end;border-bottom-right-radius:4px}\n.bub .t{font-size:10px;color:var(--muted);margin-top:4px;text-align:right}\n.bub.out .t{color:rgba(255,255,255,.6)}\n.bub .sender{display:flex;align-items:center;gap:6px;margin-bottom:4px}\n.bub .sender .av{width:20px;height:20px;border-radius:50%;font-size:8px;display:grid;place-items:center;color:#fff}\n.bub .sender .nm{font-size:11px;font-weight:600;color:var(--ink)}\n.bub .sender .ty{font-size:9px;color:var(--muted);background:var(--bg);padding:0 4px;border-radius:4px}\n.bub .at{color:#1d4ed8;font-weight:700}\n.bub .rcpt{margin-left:4px}\n.bub.out .rcpt{color:rgba(255,255,255,.55)}\n.bub.out .rcpt.read{color:#38bdf8}\n.reply-quote{border-left:3px solid var(--accent);background:rgba(0,0,0,.04);padding:4px 8px;border-radius:4px;margin-bottom:5px;font-size:12px}\n.bub.out .reply-quote{background:rgba(255,255,255,.15);border-left-color:#fff}\n.reply-quote .rq-name{display:block;font-weight:700;font-size:11px}\n.reply-quote .rq-text{opacity:.8}\n.msg-image{display:flex;align-items:center;gap:8px;background:rgba(0,0,0,.04);padding:14px;border-radius:8px;font-size:12px}\n.bub.out .msg-image{background:rgba(255,255,255,.15)}\n.msg-file{display:flex;align-items:center;gap:8px;background:rgba(0,0,0,.04);padding:10px 12px;border-radius:8px;font-size:12px}\n.bub.out .msg-file{background:rgba(255,255,255,.15)}\n.msg-file .fn{font-weight:600}\n.msg-file .fs{opacity:.7;font-size:11px}\n.date-sep{text-align:center;font-size:11px;color:var(--muted);padding:8px 0}\n.date-sep span{background:var(--border);padding:3px 12px;border-radius:12px}\n.sys-event{text-align:center;font-size:11px;color:var(--muted);font-style:italic;padding:5px 0}\n.chat-banner{margin:6px 12px;padding:10px 14px;border-radius:8px;font-size:12px;line-height:1.5}\n.chat-banner.warn{background:#fef3c7;color:#92400e;border:1px solid #fde68a}\n.chat-banner.err{background:#fee2e2;color:#991b1b;border:1px solid #fecaca}\n.new-sep{text-align:center;font-size:11px;color:#2563eb;padding:6px 0;font-weight:600;position:relative}\n.new-sep::before{content:'';position:absolute;left:0;right:0;top:50%;border-top:1px solid #93c5fd;z-index:0}\n.new-sep span{position:relative;z-index:1;background:var(--bg);padding:0 10px;border-radius:8px}\n.composer{background:var(--card);border-top:1px solid var(--border);padding:9px 14px;display:flex;gap:8px;align-items:center}\n.composer input{flex:1;border:1px solid var(--border);border-radius:20px;padding:9px 14px;font-size:13px;background:var(--card)}\n.composer input:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.exp-banner,.disc-banner{display:flex;align-items:center;gap:12px;padding:12px 14px;border-top:1px solid var(--border);background:var(--card)}\n.exp-banner .db-title,.disc-banner .db-title{font-size:13px;font-weight:700}\n.exp-banner .db-sub,.disc-banner .db-sub{font-size:11px;color:var(--muted);margin-top:2px}\n.disc-banner.err{background:#fef2f2;border-color:#fecaca}\n.disc-banner.err .db-title{color:#dc2626}\n.disc-banner.err .db-sub{color:#b91c1c}\n#connBanner{margin:12px 14px;padding:14px;border-radius:10px;border:1px solid #fecaca;background:#fef2f2;display:flex;flex-direction:column;gap:8px}\n.ws-empty{flex:1;display:grid;place-items:center;color:var(--muted);font-size:14px;text-align:center;gap:8px}\n.ws-empty .glyph{font-size:40px;opacity:.4}\n\n/* ── Drawer — inline at 1440, floating at 1280 ── */\n.conv-drawer{width:320px;flex:0 0 320px;background:var(--card);border-left:1px solid var(--border);overflow-y:auto;display:none}\n.conv-drawer.open{display:block}\n/* At 1280 drawer floats over workspace */\n.conv-layout.drawerFloat .conv-drawer.open{position:absolute;right:0;top:0;bottom:0;z-index:20;box-shadow:-4px 0 16px rgba(0,0,0,.1)}\n.dsec{padding:14px;border-bottom:1px solid var(--border)}\n.dsec h4{font-size:12px;font-weight:700;color:var(--muted);margin-bottom:8px}\n.dk{font-size:12px;color:var(--muted)}.dv{font-size:13px;font-weight:600}\n/* ── Detail drawer (accordion) ── */\n.drawer-head{position:sticky;top:0;background:var(--card);z-index:2;padding:12px 14px;border-bottom:1px solid var(--border);font-weight:700;font-size:13px;display:flex;align-items:center;justify-content:space-between}\n.drawer-x{border:none;background:none;font-size:15px;cursor:pointer;color:var(--muted);padding:2px 6px;border-radius:6px}\n.drawer-x:hover{background:var(--bg);color:var(--foreground)}\n.drawer-scrim{display:none}\n/* close-conv button: inline mode = thread-header only; drawer(float) mode = in-drawer sticky-bottom only */\n#drawerCloseConv{display:none}\n/* button visibility toggled by JS detailOpen state */\n.conv-layout.drawerFloat .conv-drawer.open{position:absolute;right:0;top:0;bottom:0;z-index:20;box-shadow:-4px 0 16px rgba(0,0,0,.1)}\n.conv-layout.drawerFloat .drawer-scrim.on{display:block;position:absolute;inset:0;z-index:15;background:rgba(0,0,0,.25)}\ndetails.dsec{padding:0;border-bottom:1px solid var(--border)}\ndetails.dsec>summary{list-style:none;cursor:pointer;padding:12px 14px;font-size:12px;font-weight:700;color:var(--fg);display:flex;align-items:center;gap:6px}\ndetails.dsec>summary::-webkit-details-marker{display:none}\ndetails.dsec>summary .dbadge{background:var(--accent,#e0e7ff);color:#4f46e5;border-radius:10px;font-size:11px;padding:0 7px;font-weight:700}\ndetails.dsec>summary .chev{margin-left:auto;transition:transform .15s;color:var(--muted)}\ndetails.dsec[open]>summary .chev{transform:rotate(180deg)}\n.dsec-body{padding:0 14px 14px}\n.drow{display:flex;justify-content:space-between;gap:12px;padding:5px 0;font-size:13px}\n.drow .dk{flex:0 0 42%}.drow .dv{text-align:right;flex:1;word-break:break-word}\n.dpill{display:inline-block;background:var(--bg);border:1px solid var(--border);border-radius:12px;padding:1px 9px;font-size:11px;font-weight:600;margin:2px 0 2px 4px}\n.dlink,.see-all{color:#4f46e5;font-weight:600;cursor:pointer;font-size:12px}\n.see-all{display:inline-block;margin-top:8px}\n.dcard{border:1px solid var(--border);border-radius:8px;padding:8px 10px;margin-top:6px}\n.dcard-t{font-size:12px;font-weight:600}.dcard-s{font-size:11px;color:var(--muted);margin-top:2px}\n.dtags{display:flex;flex-wrap:wrap;gap:4px;align-items:center}\n.dadd{border:1px dashed var(--border);border-radius:12px;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;color:var(--muted)}\n.dnote-in{width:100%;background:#fffbeb;border:1px solid var(--border);border-radius:8px;padding:7px 10px;font-size:12px;margin-bottom:8px}\n.dnote{display:flex;gap:8px;padding:8px;border-radius:8px;font-size:12px;line-height:1.4}\n.dnote.hl{background:#fffbeb}.dnote .pin{color:#eab308}\n.dpin{display:flex;gap:8px;padding:8px 0;font-size:12px;border-top:1px solid var(--border)}\n.dpin:first-child{border-top:none}.dpin-b{color:var(--fg);margin:2px 0;line-height:1.4}\n.dpin-m{color:var(--muted);font-size:11px}\n.dhist{display:flex;gap:8px;padding:8px 0;border-top:1px solid var(--border);font-size:12px}\n.dhist:first-child{border-top:none}\n.dhist .av{flex:0 0 30px;height:30px;border-radius:50%;background:var(--bg);border:1px solid var(--border);display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:700}\n.dhist-t{color:var(--muted);font-size:11px}.dhist-p{color:var(--muted);margin-top:2px}\n.dgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}\n.dthumb{aspect-ratio:1;background:var(--bg);border:1px solid var(--border);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:22px}\n.dfile{display:flex;gap:8px;padding:8px 0;border-top:1px solid var(--border);font-size:12px}\n.dfile:first-child{border-top:none}\n.fext{flex:0 0 34px;height:34px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;color:#fff}\n.fext.xlsx{background:#16a34a}.fext.pdf{background:#dc2626}.fext.doc{background:#2563eb}\n.dfile-n{font-weight:600;word-break:break-all}.dfile-m{color:var(--muted);font-size:11px;margin-top:2px}\n.dtl{position:relative;padding-left:4px}\n.dtl-i{display:flex;gap:10px;padding:6px 0;position:relative}\n.dtl-i .dot{flex:0 0 9px;height:9px;border-radius:50%;background:var(--border);margin-top:4px;z-index:1}\n.dtl-i .dot.blue{background:#2563eb}\n.dtl-i:not(:last-child)::before{content:'';position:absolute;left:4px;top:14px;bottom:-6px;width:1px;background:var(--border)}\n.dtl-t{color:var(--muted);font-size:11px}.dtl-x{font-size:12px;margin-top:1px;line-height:1.4}\n\n/* ── Filter overlay + sheets ── */\n.filter-overlay{position:fixed;inset:0;background:rgba(0,0,0,.3);z-index:200;display:flex;justify-content:center;align-items:flex-start;padding-top:60px}\n.filter-overlay.hide{display:none}\n.filter-sheet{background:var(--card);border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,.18);width:90%;max-height:80vh;overflow-y:auto;padding:20px 24px}\n.fs-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}\n/* Toggle card (visibilitas) */\n.toggle-card{display:flex;align-items:center;justify-content:space-between;padding:12px;border:1px solid var(--border);border-radius:10px}\n.toggle-card-left{display:flex;align-items:center;gap:12px}\n.toggle-card-img{width:48px;height:48px;border-radius:10px;border:1px solid var(--border);display:grid;place-items:center;font-size:20px}\n/* Switch toggle */\n.switch{position:relative;width:40px;height:22px;display:inline-block}\n.switch input{opacity:0;width:0;height:0}\n.switch .slider{position:absolute;inset:0;background:#cbd5e1;border-radius:22px;cursor:pointer;transition:.2s}\n.switch .slider::before{content:'';position:absolute;width:16px;height:16px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.2s}\n.switch.on .slider,.switch input:checked+.slider{background:var(--accent)}\n.switch.on .slider::before,.switch input:checked+.slider::before{transform:translateX(18px)}\n/* Badge pill */\n.badge-pill{display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:12px;font-size:12px;background:var(--bg);border:1px solid var(--border);font-weight:500}\n.fs-btn{padding:8px 12px;border:1px solid var(--border);border-radius:8px;background:var(--card);cursor:pointer;font-size:13px}\n.fs-btn:hover{border-color:var(--accent)}\n</style>\n\n<div class=\"conv-layout filterFull\" id=\"convLayout\">\n  <!-- SIDENAV -->\n  <aside class=\"conv-sidenav\" id=\"convSidenav\">\n    <div class=\"sn-head\">\n      <span class=\"sn-title\">Inbox</span>\n      <button class=\"sn-collapse\" onclick=\"toggleSidenav()\" title=\"Ciutkan/Lebarkan\">☰</button>\n    </div>\n    <div class=\"sn-group\" data-sec=\"personal\">\n      <button class=\"sn-disc open\" onclick=\"toggleSec(this)\"><span class=\"ic\">💬</span><span class=\"txt\"> Pesan Langsung</span><span class=\"dotind\">•</span><span class=\"chev\">›</span></button>\n      <div class=\"sn-sub\" id=\"snSubPersonal\">\n        <div class=\"sn-item active\" data-filter=\"mine\" onclick=\"pickSection(this,'mine')\"><span class=\"ic\">👤</span><span class=\"txt\">Kotak Masuk Saya</span><span class=\"cnt\" id=\"cntMine\"></span></div>\n        <div class=\"sn-item spv-only\" data-filter=\"unassigned\" onclick=\"pickSection(this,'unassigned')\"><span class=\"ic\">📭</span><span class=\"txt\">Belum Ditugaskan</span><span class=\"cnt\" id=\"cntUnassigned\"></span></div>\n        <div class=\"sn-item spv-only\" data-filter=\"all\" onclick=\"pickSection(this,'all')\"><span class=\"ic\">📥</span><span class=\"txt\">Semua</span><span class=\"cnt\" id=\"cntAll\"></span></div>\n        <div class=\"sn-item\" data-filter=\"starred\" onclick=\"pickSection(this,'starred')\"><span class=\"ic\">⭐</span><span class=\"txt\">Berbintang</span><span class=\"cnt\" id=\"cntStarred\"></span></div>\n      </div>\n    </div>\n    <div class=\"sn-div\"></div>\n    <div class=\"sn-group\" data-sec=\"group\">\n      <button class=\"sn-disc open\" onclick=\"toggleSec(this)\"><span class=\"ic\">👥</span><span class=\"txt\"> Grup</span><span class=\"dotind\">•</span><span class=\"chev\">›</span></button>\n      <div class=\"sn-sub\" id=\"snSubGroup\"></div>\n    </div>\n    <div class=\"sn-div\"></div>\n    <div class=\"sn-group\" data-sec=\"channel\">\n      <button class=\"sn-disc\" onclick=\"toggleSec(this)\"><span class=\"ic\">📡</span><span class=\"txt\"> Channel</span><span class=\"dotind\">•</span><span class=\"chev\">›</span></button>\n      <div class=\"sn-sub\" id=\"snSubChannel\" style=\"display:none\"></div>\n    </div>\n    <div class=\"sn-div\"></div>\n    <div class=\"sn-group\" data-sec=\"team\">\n      <button class=\"sn-disc\" onclick=\"toggleSec(this)\"><span class=\"ic\">🗂</span><span class=\"txt\"> Kotak Tim</span><span class=\"dotind\">•</span><span class=\"chev\">›</span><span class=\"sn-add spv-only\" title=\"Buat Tim\" onclick=\"event.stopPropagation();go('settings/inbox-team')\">＋</span></button>\n      <div class=\"sn-sub\" id=\"snSubTeam\" style=\"display:none\"></div>\n    </div>\n    <div class=\"sn-div\"></div>\n    <div class=\"sn-group\" data-sec=\"others\">\n      <button class=\"sn-disc\" onclick=\"toggleSec(this)\"><span class=\"ic\">🗃</span><span class=\"txt\"> Lainnya</span><span class=\"dotind\">•</span><span class=\"chev\">›</span></button>\n      <div class=\"sn-sub\" id=\"snSubOthers\" style=\"display:none\">\n        <div class=\"sn-item\" data-filter=\"spam\" onclick=\"pickSection(this,'spam')\"><span class=\"ic\">🚫</span><span class=\"txt\">Spam</span><span class=\"cnt\" id=\"cntSpam\"></span></div>\n        <div class=\"sn-item\" data-filter=\"junk\" onclick=\"pickSection(this,'junk')\"><span class=\"ic\">🗑</span><span class=\"txt\">Sampah</span><span class=\"cnt\" id=\"cntJunk\"></span></div>\n      </div>\n    </div>\n  </aside>\n\n  <!-- LIST -->\n  <aside class=\"conv-list\">\n    <div class=\"list-head\"><input class=\"list-search\" type=\"text\" placeholder=\"Kotak Pesan Anda\" id=\"convSearch\" oninput=\"filterConvList()\"></div>\n    <!-- Filter bar — icon mode (1280) + full mode (1440) -->\n    <div class=\"fbar\" style=\"position:relative\">\n      <!-- ICON MODE -->\n      <div class=\"fbar-icon\">\n        <div style=\"position:relative\">\n          <button class=\"fctrl\" id=\"dd-status-btn\" onclick=\"toggleDD('status')\" title=\"Terbuka / Tertutup\"><span>🚪</span> <span style=\"font-size:9px\">▾</span></button>\n          <div class=\"fmenu hide\" id=\"menu-status\">\n            <button class=\"fitem active\" onclick=\"pickStatus('open',this)\">🚪 Terbuka <span class=\"fcheck\">✓</span></button>\n            <button class=\"fitem\" onclick=\"pickStatus('closed',this)\">🚪 Tertutup <span class=\"fcheck\">✓</span></button>\n          </div>\n        </div>\n        <div style=\"position:relative\">\n          <button class=\"fctrl\" id=\"dd-read-btn\" onclick=\"toggleDD('read')\" title=\"Semua / Dibaca / Belum\"><span>💬</span> <span style=\"font-size:9px\">▾</span></button>\n          <div class=\"fmenu hide\" id=\"menu-read\">\n            <button class=\"fitem active\" onclick=\"pickRead('all',this)\">💬 Semua <span class=\"fcheck\">✓</span></button>\n            <button class=\"fitem\" onclick=\"pickRead('read',this)\">☑ Sudah dibaca <span class=\"fcheck\">✓</span></button>\n            <button class=\"fitem\" onclick=\"pickRead('unread',this)\">💬 Belum dibaca <span class=\"fcheck\">✓</span></button>\n          </div>\n        </div>\n        <div style=\"position:relative\">\n          <button class=\"fctrl\" onclick=\"toggleDD('sort')\" title=\"Urutkan\"><span>⇅</span> <span style=\"font-size:9px\">▾</span></button>\n          <div class=\"fmenu hide\" id=\"menu-sort\">\n            <button class=\"fitem active\" onclick=\"pickSort('newest',this)\">Terbaru <span class=\"fcheck\">✓</span></button>\n            <button class=\"fitem\" onclick=\"pickSort('oldest',this)\">Terlama <span class=\"fcheck\">✓</span></button>\n          </div>\n        </div>\n        <span class=\"fspacer\"></span>\n        <button class=\"fctrl fico2\" onclick=\"openModal('m-advanced')\" title=\"Filter Lanjutan\">⚗</button>\n        <button class=\"fctrl fico2\" onclick=\"openModal('m-layout')\" title=\"Visibilitas\">⚙</button>\n      </div>\n\n      <!-- FULL MODE -->\n      <div class=\"fbar-exp\">\n        <!-- Row 2: status segmented + sort -->\n        <div class=\"frow2\">\n          <div class=\"seg-status\">\n            <button class=\"seg active\" onclick=\"setStatus('open',this)\">Terbuka <span class=\"segcnt\" id=\"cntOpen\"></span></button>\n            <button class=\"seg\" onclick=\"setStatus('closed',this)\">Tertutup <span class=\"segcnt\" id=\"cntClosed\"></span></button>\n          </div>\n          <span class=\"fspacer\"></span>\n          <button class=\"fctrl-lbl\" onclick=\"toggleDD('sort')\"><span>⇅</span> <span id=\"lbl-sort\">Terbaru</span> <span style=\"font-size:9px\">▾</span></button>\n        </div>\n        <!-- Row 3: read chips + icons -->\n        <div class=\"frow2\">\n          <div class=\"fchips\">\n            <button class=\"fchip on\" onclick=\"pickReadChip('all',this)\">Semua</button>\n            <button class=\"fchip\" onclick=\"pickReadChip('read',this)\">Sudah dibaca</button>\n            <button class=\"fchip\" onclick=\"pickReadChip('unread',this)\">Belum dibaca</button>\n          </div>\n          <span class=\"fspacer\"></span>\n          <div class=\"ficons\">\n            <button class=\"fchip ico\" onclick=\"openModal('m-layout')\" title=\"Visibilitas\">⚙</button>\n            <button class=\"fchip ico\" onclick=\"openModal('m-advanced')\" title=\"Filter Lanjutan\">⚗</button>\n          </div>\n        </div>\n      </div>\n    </div>\n    <div class=\"bulk-bar\" id=\"bulkBar\">\n      <span class=\"bcount\" id=\"bulkCount\">0 dipilih</span>\n      <button onclick=\"bulkSelectAll()\" id=\"bulkAllBtn\">Pilih semua</button>\n      <button class=\"bprimary\" onclick=\"bulkStatus('closed')\">✓ Selesai</button>\n      <div class=\"bmore-wrap\">\n        <button class=\"bmore-btn\" onclick=\"toggleBulkMore(event)\">⋯ Aksi lain ▾</button>\n        <div class=\"bmore\" id=\"bulkMore\">\n          <button onclick=\"bulkTicket()\">🎫 Buat Tiket</button>\n          <button onclick=\"bulkStatus('open')\">↩ Buka Lagi</button>\n          <button onclick=\"bulkStatus('pending')\">⏳ Tunda</button>\n          <div class=\"bmore-sep\"></div>\n          <input class=\"bsel\" id=\"bulkAgent\" list=\"dlAgent\" placeholder=\"👤 Cari & tugaskan agen…\" onchange=\"bulkPickAgent(this)\">\n          <datalist id=\"dlAgent\"></datalist>\n          <input class=\"bsel\" id=\"bulkTeam\" list=\"dlTeam\" placeholder=\"🗂 Cari & tugaskan tim…\" onchange=\"bulkPickTeam(this)\">\n          <datalist id=\"dlTeam\"></datalist>\n          <input class=\"bsel\" id=\"bulkLabel\" list=\"dlLabel\" placeholder=\"🏷 Cari / ketik label…\" onchange=\"bulkLabel(this.value);this.value=''\">\n          <datalist id=\"dlLabel\"></datalist>\n          <div class=\"bmore-sep\"></div>\n          <button onclick=\"bulkRead(true)\">✓ Tandai Dibaca</button>\n          <button onclick=\"bulkRead(false)\">● Tandai Belum Dibaca</button>\n          <button class=\"bdel\" onclick=\"bulkDelete()\">🗑 Hapus</button>\n        </div>\n      </div>\n      <button class=\"bx\" onclick=\"bulkClear()\" title=\"Batal\">✕</button>\n    </div>\n    <div class=\"list-body\" id=\"convListBody\"></div>\n  </aside>\n\n  <!-- WORKSPACE -->\n  <section class=\"conv-ws\" id=\"convWs\">\n    <div class=\"ws-head\" id=\"wsHead\" style=\"display:none\">\n      <div style=\"flex:1\"><div class=\"name\" id=\"wsName\"></div><div class=\"sub\" id=\"wsSub\"></div></div>\n      <div class=\"ws-actions\">\n        <button class=\"btn\" id=\"btnCloseConv\" onclick=\"closeConv()\" style=\"font-size:12px\">Tutup Percakapan</button>\n        <button class=\"btn\" onclick=\"toggleDrawer()\" style=\"font-size:12px\">📋</button>\n      </div>\n    </div>\n    <div class=\"thread\" id=\"thread\" style=\"display:none\"></div>\n    <div class=\"composer\" id=\"composer\" style=\"display:none\"><input id=\"composeInput\" placeholder=\"Ketik balasan…\" onkeydown=\"if(event.key==='Enter')doSend()\"><button class=\"btn primary\" onclick=\"doSend()\">Kirim</button></div>\n    <div class=\"disc-banner err\" id=\"connBanner\" style=\"display:none\">\n      <div><div class=\"db-title\">🔌 Channel Terputus</div><div class=\"db-sub\">Akun channel ini tidak terhubung. Pesan tidak dapat dikirim sampai terhubung kembali.</div></div>\n      <button class=\"btn primary\" style=\"margin-left:auto;white-space:nowrap\" onclick=\"openReconnectModal()\">⟳ Hubungkan Kembali</button>\n    </div>\n    <div class=\"exp-banner\" id=\"expiredBanner\" style=\"display:none\">\n      <div><div class=\"db-title\">Percakapan Tidak Aktif</div><div class=\"db-sub\">Percakapan ini tidak aktif karena pelanggan tidak merespons dalam 24 jam. Untuk melanjutkan percakapan, silakan terlibat kembali dengan pelanggan.</div></div>\n      <button class=\"btn primary\" onclick=\"openTemplateModal()\" style=\"margin-left:auto;white-space:nowrap\">Kirim Template Pesan</button>\n    </div>\n    <div class=\"disc-banner\" id=\"discBanner\" style=\"display:none\">\n      <div><div class=\"db-title\">Perlu Menyesuaikan Nomor WA Web</div><div class=\"db-sub\">Anda tidak dapat mengirim pesan karena perlu menyesuaikan nomor di SatuInbox.</div></div>\n      <button class=\"btn\" style=\"margin-left:auto;white-space:nowrap\">⚙ Sesuaikan Akun</button>\n    </div>\n    <div class=\"ws-empty\" id=\"wsEmpty\"><div class=\"glyph\">💬</div><div><b>Pilih percakapan</b><br>Pilih percakapan dari daftar untuk mulai bekerja.</div></div>\n  </section>\n\n  <!-- DRAWER -->\n  <div class=\"drawer-scrim\" id=\"drawerScrim\" onclick=\"toggleDrawer()\"></div>\n  <aside class=\"conv-drawer\" id=\"convDrawer\">\n    <div class=\"drawer-head\"><span>📋 Detail Percakapan</span><button class=\"drawer-x\" onclick=\"toggleDrawer()\" title=\"Tutup\">✕</button></div>\n    <div id=\"drawerBody\"></div>\n  </aside>\n\n  <!-- ASSIGN AGENT MODAL -->\n  <div class=\"modal-overlay\" id=\"assignModal\">\n    <div class=\"modal\" style=\"max-width:400px\">\n      <h3>Tetapkan Agen</h3>\n      <div id=\"assignAgentList\" style=\"max-height:250px;overflow-y:auto\"></div>\n      <div class=\"modal-actions\"><button class=\"btn\" onclick=\"closeModal('assignModal')\">Batal</button></div>\n    </div>\n  </div>\n\n  <!-- CLOSE CONVERSATION CONFIRM MODAL (rule OD-03: single confirmation path) -->\n  <div class=\"modal-overlay\" id=\"resolveModal\" onclick=\"if(event.target===this)this.classList.remove('open')\">\n    <div class=\"modal\" style=\"max-width:400px\">\n      <h3>Selesaikan percakapan?</h3>\n      <p style=\"font-size:13px;color:var(--muted);margin-bottom:14px\">Percakapan akan ditandai selesai dan pindah dari antrean aktif.</p>\n      <div class=\"modal-actions\">\n        <button class=\"btn\" onclick=\"document.getElementById('resolveModal').classList.remove('open')\">Batal</button>\n        <button class=\"btn danger\" onclick=\"doCloseConv()\">Selesaikan</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- RECONNECT CHANNEL MODAL (2 conditions: select new account OR scan QR) -->\n  <div class=\"modal-overlay\" id=\"reconnectModal\" onclick=\"if(event.target===this)this.classList.remove('open')\">\n    <div class=\"modal\" style=\"max-width:440px\">\n      <h3 id=\"rcTitle\">Hubungkan Kembali Channel</h3>\n      <div id=\"rcBody\"></div>\n    </div>\n  </div>\n\n  <!-- ADD LABEL MODAL -->\n  <div class=\"modal-overlay\" id=\"labelModal\" onclick=\"if(event.target===this)this.classList.remove('open')\">\n    <div class=\"modal\" style=\"max-width:360px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px\">\n        <h3 style=\"margin:0\">Tambah Label</h3>\n        <button class=\"btn\" style=\"padding:4px 8px\" onclick=\"document.getElementById('labelModal').classList.remove('open')\">✕</button>\n      </div>\n      <input id=\"labelSearch\" placeholder=\"Cari atau buat label…\" oninput=\"filterLabels(this.value)\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-bottom:10px;background:transparent;color:inherit\">\n      <div id=\"labelList\" style=\"max-height:200px;overflow-y:auto\"></div>\n      <div id=\"labelCreate\" style=\"display:none;margin-top:8px;padding:10px;border:1px dashed var(--border);border-radius:8px;cursor:pointer;color:var(--primary);font-size:13px\" onclick=\"createLabel()\">＋ Buat label baru</div>\n    </div>\n  </div>\n\n  <!-- ADD PROSPEK (LEAD) MODAL — fields from FE AddLeadModal.tsx -->\n  <div class=\"modal-overlay\" id=\"prospekModal\" onclick=\"if(event.target===this)this.classList.remove('open')\">\n    <div class=\"modal\" style=\"max-width:500px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px\">\n        <h3 style=\"margin:0\">＋ Buat Prospek</h3>\n        <button class=\"btn\" style=\"padding:4px 8px\" onclick=\"document.getElementById('prospekModal').classList.remove('open')\">✕</button>\n      </div>\n      <div style=\"display:flex;flex-direction:column;gap:12px\">\n        <div>\n          <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Judul Prospek <span style=\"color:#ef4444\">*</span></label>\n          <input id=\"pTitle\" placeholder=\"Masukkan judul prospek\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n        </div>\n        <div>\n          <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Kotak Tim <span style=\"color:#ef4444\">*</span></label>\n          <select id=\"pTeam\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:inherit\"><option value=\"\">Pilih kotak tim</option></select>\n        </div>\n        <div>\n          <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Penerima (Agen) <span style=\"color:#ef4444\">*</span></label>\n          <select id=\"pAssignee\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:inherit\"><option value=\"\">Pilih agen</option></select>\n        </div>\n        <hr style=\"border:none;border-top:1px solid var(--border);margin:4px 0\">\n        <div style=\"font-size:12px;font-weight:600;color:var(--muted)\">Kontak</div>\n        <div>\n          <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Sumber Channel</label>\n          <select id=\"pChannel\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:inherit\"><option value=\"\">Pilih channel</option></select>\n        </div>\n        <div>\n          <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">No. WhatsApp / Email</label>\n          <input id=\"pContactValue\" placeholder=\"Nomor HP atau email kontak\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\">\n          <div>\n            <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Nama Kontak <span style=\"color:#ef4444\">*</span></label>\n            <input id=\"pName\" placeholder=\"Ketik untuk cari kontak…\" list=\"dlContacts\" oninput=\"onProspekContactSearch(this.value)\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n            <datalist id=\"dlContacts\"></datalist>\n            <div id=\"pContactMatch\" style=\"font-size:10px;color:var(--muted);margin-top:2px\"></div>\n          </div>\n          <div>\n            <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Nama Kantor</label>\n            <input id=\"pOffice\" placeholder=\"Nama perusahaan\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n          </div>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\">\n          <div>\n            <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Jabatan</label>\n            <input id=\"pJobTitle\" placeholder=\"Jabatan kontak\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n          </div>\n          <div>\n            <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Email</label>\n            <input id=\"pEmail\" type=\"email\" placeholder=\"email@contoh.com\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n          </div>\n        </div>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:10px\">\n          <div>\n            <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">No. Telp Kantor</label>\n            <input id=\"pOfficePhone\" placeholder=\"021-xxxxxxx\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n          </div>\n          <div>\n            <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Tipe Bisnis</label>\n            <input id=\"pBusinessType\" placeholder=\"Retail, F&B, dll\" list=\"dlBusinessType\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit\">\n            <datalist id=\"dlBusinessType\"><option value=\"Retail\"><option value=\"F&B\"><option value=\"Teknologi\"><option value=\"Manufaktur\"><option value=\"Jasa\"><option value=\"Kesehatan\"><option value=\"Pendidikan\"><option value=\"Properti\"></datalist>\n          </div>\n        </div>\n        <div>\n          <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:4px\">Alamat</label>\n          <textarea id=\"pAddress\" rows=\"2\" placeholder=\"Alamat lengkap\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:inherit;resize:vertical\"></textarea>\n        </div>\n      </div>\n      <div style=\"display:flex;justify-content:flex-end;gap:8px;margin-top:16px\">\n        <button class=\"btn\" onclick=\"document.getElementById('prospekModal').classList.remove('open')\">Batal</button>\n        <button class=\"btn primary\" onclick=\"doCreateProspek()\">Simpan Prospek</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- TEMPLATE MESSAGE MODAL (WA API 24h expired) -->\n  <div class=\"modal-overlay\" id=\"templateModal\" onclick=\"if(event.target===this)this.classList.remove('open')\">\n    <div class=\"modal\" style=\"max-width:520px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px\">\n        <h3 style=\"margin:0\">📋 Template Pesan WhatsApp</h3>\n        <button class=\"btn\" style=\"padding:4px 8px\" onclick=\"document.getElementById('templateModal').classList.remove('open')\">✕</button>\n      </div>\n      <input id=\"tplSearch\" placeholder=\"Cari template…\" oninput=\"filterTemplates(this.value)\" style=\"width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-bottom:12px;background:transparent;color:inherit\">\n      <div id=\"tplList\" style=\"max-height:360px;overflow-y:auto;display:flex;flex-direction:column;gap:8px\"></div>\n    </div>\n  </div>\n\n  <!-- TEMPLATE PREVIEW MODAL -->\n  <div class=\"modal-overlay\" id=\"tplPreviewModal\" onclick=\"if(event.target===this)this.classList.remove('open')\">\n    <div class=\"modal\" style=\"max-width:440px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:14px\">\n        <h3 style=\"margin:0\" id=\"tplPreviewTitle\">Preview Template</h3>\n        <button class=\"btn\" style=\"padding:4px 8px\" onclick=\"document.getElementById('tplPreviewModal').classList.remove('open')\">✕</button>\n      </div>\n      <div id=\"tplPreviewBody\" style=\"font-size:13px;line-height:1.5;padding:14px;border-radius:10px;background:var(--bg);border:1px solid var(--border);margin-bottom:12px\"></div>\n      <div id=\"tplPreviewButtons\" style=\"display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px\"></div>\n      <div style=\"display:flex;justify-content:flex-end;gap:8px\">\n        <button class=\"btn\" onclick=\"document.getElementById('tplPreviewModal').classList.remove('open')\">Batal</button>\n        <button class=\"btn primary\" onclick=\"sendTemplate()\">Kirim Template</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- CHANGE MAX CONVERSATION MODAL -->\n  <div class=\"modal-overlay\" id=\"changeMaxModal\">\n    <div class=\"modal\" style=\"max-width:520px\">\n      <h3>Ubah Maksimum Percakapan</h3>\n      <p id=\"cmAgentInfo\" style=\"font-size:13px;color:var(--muted);margin-bottom:14px\"></p>\n      <div style=\"display:flex;align-items:flex-end;gap:14px\">\n        <div style=\"flex:1\"><label style=\"font-size:12px;color:var(--muted)\">Batas Saat Ini</label><input id=\"cmCurrent\" type=\"number\" readonly style=\"width:100%;padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--bg)\"></div>\n        <span style=\"font-size:18px;color:var(--muted);padding-bottom:9px\">→</span>\n        <div style=\"flex:1\"><label style=\"font-size:12px;color:var(--muted)\">Batas Baru</label><input id=\"cmInput\" type=\"number\" min=\"1\" placeholder=\"Masukkan batas baru\" oninput=\"cmValidate()\" style=\"width:100%;padding:8px;border:1px solid var(--border);border-radius:8px\"></div>\n      </div>\n      <div class=\"modal-actions\">\n        <button class=\"btn\" onclick=\"closeModal('changeMaxModal')\">Batal</button>\n        <button class=\"btn primary\" id=\"cmSubmit\" onclick=\"saveMaxAndAssign()\" disabled>Simpan Perubahan</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- VISIBILITAS MODAL — Tata Letak dan Visibilitas -->\n  <div class=\"filter-overlay hide\" id=\"m-layout\">\n    <div class=\"filter-sheet\" style=\"max-width:560px\">\n      <div class=\"fs-head\"><span style=\"font-weight:600;font-size:16px\">Tata Letak dan Visibilitas</span>\n        <span onclick=\"closeModal('m-layout')\" style=\"cursor:pointer;font-size:18px;color:var(--muted)\">&times;</span></div>\n      <h3 style=\"font-size:14px;font-weight:600;color:var(--ink);margin-bottom:12px\">Visibilitas</h3>\n      <div style=\"display:flex;flex-direction:column;gap:12px\">\n        <div class=\"toggle-card\">\n          <div class=\"toggle-card-left\">\n            <div class=\"toggle-card-img\" style=\"background:#f0fdf4;border-color:#dcfce7\">🟢</div>\n            <div>\n              <div style=\"font-size:13px;font-weight:500;color:var(--ink)\">Tampilkan Lencana WhatsApp Web</div>\n              <div style=\"font-size:12px;color:var(--muted);margin-top:2px\">Tampilkan lencana yang menunjukkan akun WhatsApp Web asal setiap percakapan.</div>\n            </div>\n          </div>\n          <label class=\"switch on\"><input type=\"checkbox\" checked onchange=\"toggleVis('waBadge',this.checked)\"><span class=\"slider\"></span></label>\n        </div>\n        <div class=\"toggle-card\">\n          <div class=\"toggle-card-left\">\n            <div class=\"toggle-card-img\" style=\"background:#eff6ff;border-color:#dbeafe\">🏷️</div>\n            <div>\n              <div style=\"font-size:13px;font-weight:500;color:var(--ink)\">Tampilkan Tag</div>\n              <div style=\"font-size:12px;color:var(--muted);margin-top:2px\">Tampilkan tag yang ditetapkan dalam daftar percakapan Anda untuk memudahkan melihat kategori atau topik</div>\n            </div>\n          </div>\n          <label class=\"switch on\"><input type=\"checkbox\" checked onchange=\"toggleVis('tags',this.checked)\"><span class=\"slider\"></span></label>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- FILTER LANJUTAN MODAL — AdvanceFilterModal (Agents + Tags) -->\n  <div class=\"filter-overlay hide\" id=\"m-advanced\">\n    <div class=\"filter-sheet\" style=\"max-width:480px\">\n      <div class=\"fs-head\"><span style=\"font-weight:600;font-size:16px\">Filter Lanjutan</span>\n        <span onclick=\"closeModal('m-advanced')\" style=\"cursor:pointer;font-size:18px;color:var(--muted)\">&times;</span></div>\n      <div style=\"display:flex;flex-direction:column;gap:24px;padding:16px 0\">\n        <section>\n          <p style=\"font-size:13px;font-weight:500;color:var(--muted);margin-bottom:8px\">Agen</p>\n          <div id=\"advAgentList\" style=\"max-height:160px;overflow-y:auto;border:1px solid var(--border);border-radius:8px\"></div>\n          <div id=\"selected-agents\" style=\"display:flex;flex-wrap:wrap;gap:6px;margin-top:8px\"></div>\n        </section>\n        <section>\n          <p style=\"font-size:13px;font-weight:500;color:var(--muted);margin-bottom:8px\">Tag</p>\n          <div id=\"advTagList\" style=\"display:flex;flex-wrap:wrap;gap:6px\"></div>\n          <div id=\"selected-tags\" style=\"display:flex;flex-wrap:wrap;gap:6px;margin-top:8px\"></div>\n        </section>\n        <div style=\"display:flex;gap:8px;justify-content:flex-end\">\n          <button class=\"btn\" onclick=\"resetAdvFilter()\">Reset</button>\n          <button class=\"btn primary\" onclick=\"applyAdvFilter();closeModal('m-advanced')\">Terapkan</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n// ── State ──\nlet activeConvId=null, drawerOpen=false, detailOpen=true, sidenavCollapsed=false, filterMode='full', currentFilter='mine', activeChannel=null, activeTeam=null, activeGroupChannel=null;\nconst bulkSel=new Set();\nconst layout=()=>document.getElementById('convLayout');\n\n// ── Sidenav toggle (collapse/expand + peek) — behaviour = proto lama ──\nfunction toggleSidenav(){\n  sidenavCollapsed=!sidenavCollapsed;\n  layout().classList.toggle('sidenavCollapsed',sidenavCollapsed);\n  document.getElementById('convSidenav').classList.remove('peek');\n}\n// Peek: collapsed rail → klik expand overlay; klik child pilih+tutup; klik luar tutup (mode 'click' spt lama)\nlet peekMode='click'; // 'click' | 'hover'\nfunction setPeekMode(m){peekMode=m;document.getElementById('convSidenav').classList.remove('peek');}\n(function(){\n  const sn=document.getElementById('convSidenav');\n  sn.addEventListener('mouseenter',()=>{if(peekMode==='hover'&&sidenavCollapsed)sn.classList.add('peek')});\n  sn.addEventListener('mouseleave',()=>{if(peekMode==='hover')sn.classList.remove('peek')});\n  sn.addEventListener('click',e=>{\n    if(peekMode!=='click'||!sidenavCollapsed)return;\n    if(e.target.closest('.sn-collapse'))return;\n    const open=sn.classList.contains('peek');\n    if(!open){e.stopPropagation();sn.classList.add('peek');return;} // rail tertutup → buka peek\n    if(e.target.closest('.sn-disc')){e.stopPropagation();return;} // header section → biarkan toggleSec, peek tetap\n    if(e.target.closest('.sn-item')){e.stopPropagation();sn.classList.remove('peek');return;} // child → onclick item jalan + tutup peek\n    e.stopPropagation();\n  });\n  document.addEventListener('click',e=>{if(peekMode==='click'&&!e.target.closest('.conv-sidenav'))sn.classList.remove('peek')});\n})();\n\nfunction toggleSec(btn){\n  btn.classList.toggle('open');\n  const sub=btn.nextElementSibling;\n  if(sub)sub.style.display=btn.classList.contains('open')?'':'none';\n}\n\n// ── Filter state ──\nlet fStatus='open', fRead='all', fSort='newest';\n\nfunction toggleDD(name){\n  document.querySelectorAll('.fmenu').forEach(m=>{if(m.id!=='menu-'+name)m.classList.add('hide')});\n  const m=document.getElementById('menu-'+name);\n  if(m)m.classList.toggle('hide');\n}\nfunction closeAllDD(){document.querySelectorAll('.fmenu').forEach(m=>m.classList.add('hide'))}\ndocument.addEventListener('click',e=>{if(!e.target.closest('.fmenu,.fctrl,.fctrl-lbl'))closeAllDD()});\ndocument.addEventListener('click',e=>{if(!e.target.closest('.bmore-wrap')){const m=document.getElementById('bulkMore');if(m)m.classList.remove('on');}});\n\nfunction pickStatus(v,el){\n  fStatus=v;\n  el.closest('.fmenu').querySelectorAll('.fitem').forEach(i=>i.classList.remove('active'));\n  el.classList.add('active');\n  closeAllDD();renderConvList();\n}\nfunction pickRead(v,el){\n  fRead=v;\n  el.closest('.fmenu').querySelectorAll('.fitem').forEach(i=>i.classList.remove('active'));\n  el.classList.add('active');\n  closeAllDD();renderConvList();\n}\nfunction pickSort(v,el){\n  fSort=v;\n  el.closest('.fmenu').querySelectorAll('.fitem').forEach(i=>i.classList.remove('active'));\n  el.classList.add('active');\n  const lbl=document.getElementById('lbl-sort');if(lbl)lbl.textContent=v==='newest'?'Terbaru':'Terlama';\n  closeAllDD();renderConvList();\n}\nfunction setStatus(v,el){\n  fStatus=v;\n  el.closest('.seg-status').querySelectorAll('.seg').forEach(s=>s.classList.remove('active'));\n  el.classList.add('active');\n  renderConvList();\n}\nfunction pickReadChip(v,el){\n  fRead=v;\n  document.querySelectorAll('.fchips .fchip').forEach(c=>c.classList.remove('on'));\n  el.classList.add('on');\n  renderConvList();\n}\n\nfunction clearSelHighlight(){document.querySelectorAll('.conv-sidenav .sn-item.active').forEach(i=>i.classList.remove('active'))}\n\n// Accordion: buka section berisi item aktif, tutup lainnya\nfunction openParentSec(el){\n  const sec=el.closest('.sn-group').dataset.sec;\n  const chatPair=sec==='personal'||sec==='group';\n  document.querySelectorAll('.conv-sidenav .sn-group').forEach(g=>{\n    const disc=g.querySelector('.sn-disc'),sub=g.querySelector('.sn-sub');\n    const s=g.dataset.sec;\n    const open=chatPair?(s==='personal'||s==='group'):(s===sec);\n    if(disc)disc.classList.toggle('open',open);\n    if(sub)sub.style.display=open?'':'none';\n  });\n}\n\nfunction pickSection(el,filter){\n  clearSelHighlight();openParentSec(el);\n  el.classList.add('active');\n  currentFilter=filter;activeChannel=null;activeTeam=null;activeGroupChannel=null;\n  renderConvList();\n}\nfunction pickChannel(el,id){\n  clearSelHighlight();openParentSec(el);\n  el.classList.add('active');\n  activeChannel=id;activeTeam=null;activeGroupChannel=null;currentFilter='mine';\n  renderConvList();\n}\nfunction pickTeam(el,id){\n  clearSelHighlight();openParentSec(el);\n  el.classList.add('active');\n  activeTeam=id;activeChannel=null;activeGroupChannel=null;currentFilter='mine';\n  renderConvList();\n}\nfunction pickGroupChannel(el,ch){\n  clearSelHighlight();openParentSec(el);\n  el.classList.add('active');\n  activeGroupChannel=ch;activeChannel=null;activeTeam=null;currentFilter='group';\n  renderConvList();\n}\n\n// Render channel + team sidenav sections from seed\nfunction renderSideSections(){\n  const chEl=document.getElementById('snSubChannel');\n  if(chEl)chEl.innerHTML=(DB.channels||[]).map(c=>\n    `<div class=\"sn-item\" data-cnt=\"${c.count}\" onclick=\"pickChannel(this,'${c.id}')\"><span class=\"ic\">${c.icon}</span><span class=\"txt\">${c.title}</span><span class=\"cnt\">${c.count}</span></div>`).join('');\n  const tmEl=document.getElementById('snSubTeam');\n  if(tmEl)tmEl.innerHTML=(DB.teams||[]).map(t=>\n    `<div class=\"sn-item\" data-cnt=\"${t.count}\" onclick=\"pickTeam(this,'${t.id}')\"><span class=\"ic\" style=\"color:${t.color}\">${t.icon}</span><span class=\"txt\">${t.title}</span><span class=\"cnt\">${t.count}</span></div>`).join('');\n  const gpEl=document.getElementById('snSubGroup');\n  if(gpEl){\n    const gc=ch=>DB.conversations.filter(c=>c.isGroup&&c.channel===ch);\n    const gitem=(ch,icon,label)=>{const u=gc(ch).reduce((s,c)=>s+(c.unread||0),0);\n      return`<div class=\"sn-item\" onclick=\"pickGroupChannel(this,'${ch}')\"><span class=\"ic\">${icon}</span><span class=\"txt\">${label}</span>${u?`<span class=\"cnt\">${u}</span>`:''}</div>`;};\n    gpEl.innerHTML=gitem('whatsapp-web','💻','WhatsApp Web')+gitem('whatsapp-api','🟢','WhatsApp API');\n  }\n}\n\n// ── Viewport driver ──\nfunction setVp(w){\n  sidenavCollapsed=w<=1280;\n  layout().classList.toggle('sidenavCollapsed',sidenavCollapsed);\n  layout().classList.toggle('drawerFloat',w<=1280);\n  filterMode=w<=1280?'icon':'full';\n  layout().classList.toggle('filterIcon',filterMode==='icon');\n  layout().classList.toggle('filterFull',filterMode==='full');\n  if(sidenavCollapsed)document.getElementById('convSidenav').classList.remove('peek');\n}\nwindow.addEventListener('resize',()=>setVp(window.innerWidth));\n\n// ── Render conversation list ──\nfunction renderConvList(){\n  const body=document.getElementById('convListBody');\n  const q=(document.getElementById('convSearch')?.value||'').toLowerCase();\n  const isGroup=currentFilter==='group';\n  let convs=DB.conversations.filter(c=>{\n    if(isGroup)return c.isGroup&&(!activeGroupChannel||c.channel===activeGroupChannel);\n    if(c.isGroup)return false;\n    // Status filter\n    if(fStatus==='open'&&c.status==='closed')return false;\n    if(fStatus==='closed'&&c.status!=='closed')return false;\n    // Sidenav section filter\n    if(currentFilter==='mine'&&c.assignee!=='u1')return false;\n    if(currentFilter==='unassigned'&&c.assignee)return false;\n    if(currentFilter==='starred'&&!c.pinned)return false;\n    if(currentFilter==='spam'&&!c.spam)return false;\n    if(currentFilter==='junk'&&!c.junk)return false;\n    if(currentFilter!=='spam'&&c.spam)return false;\n    if(currentFilter!=='junk'&&c.junk)return false;\n    // Read filter\n    if(fRead==='unread'&&!c.unread)return false;\n    if(fRead==='read'&&c.unread)return false;\n    // Channel filter (from Channel section)\n    if(activeChannel&&c.channel!==activeChannel)return false;\n    // Team filter (from Team Inbox section)\n    if(activeTeam&&c.teamId!==activeTeam)return false;\n    // Advanced filter: agents\n    if(advAgents.length&&!advAgents.includes(c.assignee))return false;\n    // Advanced filter: tags\n    if(advTags.length){\n      const ct2=DB.contacts.find(x=>x.id===c.contactId);\n      if(!ct2||!advTags.some(t=>(ct2.tags||[]).includes(t)))return false;\n    }\n    // Search\n    if(q){\n      const ct=DB.contacts.find(x=>x.id===c.contactId);\n      const nm=ct?ct.name.toLowerCase():'';\n      const msg=(c.lastMsg||'').toLowerCase();\n      if(!nm.includes(q)&&!msg.includes(q))return false;\n    }\n    return true;\n  });\n  // Sort\n  convs.sort((a,b)=>{\n    if(fSort==='oldest')return new Date(a.lastTime)-new Date(b.lastTime);\n    return(b.pinned?1:0)-(a.pinned?1:0)||new Date(b.lastTime)-new Date(a.lastTime);\n  });\n  body.innerHTML=convs.map(c=>{\n    const ct=DB.contacts.find(x=>x.id===c.contactId);\n    const name=c.isGroup?(c.groupName||'Group'):ct?ct.name:'Unknown';\n    const initials=name.split(' ').map(w=>w[0]).join('').slice(0,2);\n    const chObj=DB.channels.find(x=>x.id===c.channel);\n    const ch=visState.waBadge?(chObj?.icon||'💬'):'';\n    const sel=c.id===activeConvId?'sel':'';\n    const expired=c.expired24h?'<span class=\"expired-tag\">24h lewat</span>':'';\n    const disc=(chObj&&chObj.connected===false)?'<span class=\"disc-dot\" title=\"Channel terputus\"></span>':'';\n    const mention=c.mentionTo?'<span class=\"mention\">@</span>':'';\n    const unread=c.unread?`<span class=\"unread\">${c.unread}</span>`:'';\n    const tags=visState.tags?(ct?.tags||[]).map(t=>`<span class=\"expired-tag\" style=\"background:#eff6ff;color:#2563eb;border-color:#dbeafe\">${t}</span>`).join(''):'';\n    return`<div class=\"conv-row ${sel}\" onclick=\"selectConv('${c.id}')\">\n      <label class=\"av-wrap\" onclick=\"event.stopPropagation()\">\n        <div class=\"av\" style=\"background:${randColor(name)}\">${initials}</div>\n        <input type=\"checkbox\" class=\"bchk\" ${bulkSel.has(c.id)?'checked':''} onclick=\"event.stopPropagation();toggleBulk('${c.id}',this.checked)\">\n      </label>\n      <div class=\"body\"><div class=\"name-row\">${ch}<span class=\"name\">${name}</span>${expired}${disc}${tags}</div><div class=\"prev\">${c.lastMsg||''}</div></div>\n      <div class=\"meta\"><span class=\"time\">${fmtTime(c.lastTime)}</span>${mention}${unread}</div>\n    </div>`;\n  }).join('');\n  // Counts\n  const allC=DB.conversations.filter(c=>!c.isGroup&&!c.spam);\n  const el=id=>document.getElementById(id);\n  if(el('cntAll'))el('cntAll').textContent=allC.length;\n  if(el('cntMine'))el('cntMine').textContent=allC.filter(c=>c.assignee==='u1').length;\n  if(el('cntUnassigned'))el('cntUnassigned').textContent=allC.filter(c=>!c.assignee).length;\n  if(el('cntStarred'))el('cntStarred').textContent=DB.conversations.filter(c=>!c.isGroup&&c.pinned).length;\n  if(el('cntSpam'))el('cntSpam').textContent=DB.conversations.filter(c=>c.spam).length;\n  if(el('cntJunk'))el('cntJunk').textContent=DB.conversations.filter(c=>c.junk).length;\n  // Status counts for segmented control\n  if(el('cntOpen'))el('cntOpen').textContent=DB.conversations.filter(c=>!c.isGroup&&c.status!=='closed').length;\n  if(el('cntClosed'))el('cntClosed').textContent=DB.conversations.filter(c=>!c.isGroup&&c.status==='closed').length;\n}\n\n// ── Select conversation ──\n// ── Bulk actions ──\nfunction toggleBulk(id,on){on?bulkSel.add(id):bulkSel.delete(id);syncBulkBar();}\nfunction syncBulkBar(){\n  const bar=document.getElementById('bulkBar');if(!bar)return;\n  bar.classList.toggle('on',bulkSel.size>0);\n  const c=document.getElementById('bulkCount');if(c)c.textContent=`${bulkSel.size} dipilih`;\n}\nfunction bulkClear(){bulkSel.clear();renderConvList();syncBulkBar();}\nfunction bulkApply(fn){bulkSel.forEach(id=>{const c=DB.conversations.find(x=>x.id===id);if(c)fn(c);});saveStore();bulkClear();if(typeof renderThread==='function'&&activeConvId)renderConvList();}\nfunction bulkStatus(s){bulkApply(c=>c.status=s);}\nfunction toggleBulkMore(e){e.stopPropagation();document.getElementById('bulkMore').classList.toggle('on');}\nfunction bulkTicket(){\n  const n=bulkSel.size;let made=0;\n  bulkSel.forEach(id=>{\n    const c=DB.conversations.find(x=>x.id===id);if(!c)return;\n    const nm=c.isGroup?(c.groupName||'Grup'):((DB.contacts.find(x=>x.id===c.contactId)||{}).name||'Pelanggan');\n    DB.tickets.push({id:'tk'+Date.now()+made,subject:`Tiket dari percakapan: ${nm}`,conversationId:c.id,contactId:c.contactId||null,status:'open',priority:'medium',assignee:c.assignee||'u1',teamId:c.teamId||'t1',createdAt:new Date().toISOString()});\n    made++;\n  });\n  saveStore();bulkClear();\n  alert(`${made} tiket dibuat dari ${n} percakapan.`);\n}\nfunction bulkAssignAgent(uid){if(uid)bulkApply(c=>c.assignee=uid);}\nfunction bulkAssignTeam(tid){if(tid)bulkApply(c=>c.teamId=tid);}\nfunction bulkPickAgent(inp){const u=DB.users.find(x=>x.name===inp.value);inp.value='';if(u)bulkAssignAgent(u.id);}\nfunction bulkPickTeam(inp){const t=DB.teams.find(x=>x.title===inp.value);inp.value='';if(t)bulkAssignTeam(t.id);}\nfunction bulkRead(read){bulkApply(c=>c.unread=read?0:(c.unread||1));}\nfunction bulkLabel(lb){if(!lb)return;bulkApply(c=>{c.labels=c.labels||[];if(!c.labels.includes(lb))c.labels.push(lb);});}\nfunction bulkSelectAll(){\n  document.querySelectorAll('#convListBody .conv-row .bchk').forEach(cb=>{\n    const id=cb.getAttribute('onclick').match(/toggleBulk\\('([^']+)'/)[1];bulkSel.add(id);\n  });\n  renderConvList();syncBulkBar();\n}\nfunction fillBulkDropdowns(){\n  const opt=(dlId,vals)=>{const dl=document.getElementById(dlId);if(dl&&!dl.children.length)vals.forEach(v=>{const o=document.createElement('option');o.value=v;dl.appendChild(o);});};\n  opt('dlAgent',DB.users.map(u=>u.name));\n  opt('dlTeam',DB.teams.map(t=>t.title));\n  opt('dlLabel',['VIP','Prioritas','Follow-up','Komplain','Spam']);\n}\nfunction bulkDelete(){\n  if(!confirm(`Hapus ${bulkSel.size} percakapan? Tindakan tidak bisa dibatalkan.`))return;\n  bulkSel.forEach(id=>{DB.conversations=DB.conversations.filter(c=>c.id!==id);if(activeConvId===id)activeConvId=null;});\n  saveStore();bulkClear();\n}\n\nfunction selectConv(id){\n  activeConvId=id;\n  const c=DB.conversations.find(x=>x.id===id);if(!c)return;\n  renderConvList();\n  document.getElementById('wsEmpty').style.display='none';\n  document.getElementById('wsHead').style.display='';\n  document.getElementById('thread').style.display='';\n  const ct=c.contactId?DB.contacts.find(x=>x.id===c.contactId):null;\n  const name=c.isGroup?(c.groupName||'Group'):ct?ct.name:'Unknown';\n  const sub=c.isGroup?`${c.participants?.length||0} peserta · ${c.channel==='whatsapp-api'?'WhatsApp API':'WhatsApp'} · Grup`:\n    `${ct?.phone||''} · ${c.channel==='whatsapp-api'?'WhatsApp API':'WhatsApp Web'} · ${c.status||'open'}`;\n  document.getElementById('wsName').textContent=name;\n  document.getElementById('wsSub').textContent=sub;\n  // Close button: initial visibility based on mode + detail state\n  const isFloat=layout().classList.contains('drawerFloat');\n  if(c.isGroup){\n    document.getElementById('btnCloseConv').style.display='none';\n    const dcb=document.getElementById('drawerCloseConv');if(dcb)dcb.style.display='none';\n  } else {\n    drawerOpen=false;\n    detailOpen=!isFloat; // drawer default=closed, inline default=open\n    const drawer=document.getElementById('convDrawer');\n    if(isFloat){drawer.classList.remove('open');drawer.style.display='';}\n    else{drawer.style.display=detailOpen?'block':'none';}\n  }\n  // Banners\n  const exp=c.expired24h;\n  const chObj2=DB.channels.find(x=>x.id===c.channel);\n  const disc=chObj2&&chObj2.connected===false;\n  document.getElementById('expiredBanner').style.display=exp?'':'none';\n  document.getElementById('connBanner').style.display=disc?'':'none';\n  document.getElementById('composer').style.display=(exp||disc)?'none':'';\n  renderThread(id);\n  renderDrawer(c,ct);\n  // MUST run after renderDrawer — innerHTML rebuild destroys button inline styles\n  updateCloseBtn(isFloat?false:detailOpen);\n}\n\n// ── Render thread ──\nfunction renderThread(id){\n  const el=document.getElementById('thread');\n  const msgs=DB.threads[id]||[];\n  if(!msgs.length){el.innerHTML='<div class=\"ws-empty\" style=\"padding:40px\"><div class=\"glyph\">💬</div><div>Belum ada pesan</div></div>';return}\n  const isGroup=DB.conversations.find(c=>c.id===id)?.isGroup;\n  el.innerHTML=msgs.map(m=>{\n    // Date separator\n    if(m.dateSep)return`<div class=\"date-sep\"><span>${m.dateSep}</span></div>`;\n    // New-message separator\n    if(m.newSep)return`<div class=\"new-sep\"><span>Pesan baru</span></div>`;\n    // System event (assigned / closed / reopened)\n    if(m.system)return`<div class=\"sys-event\">${m.system}</div>`;\n    // 24h window expired banner\n    if(m.expiredBanner)return`<div class=\"chat-banner warn\">⚠️ Sesi 24 jam WhatsApp telah berakhir. Anda hanya dapat mengirim template pesan.</div>`;\n    // Channel disconnected banner\n    if(m.disconnectedBanner)return`<div class=\"chat-banner err\">🔌 Channel terputus. Pesan tidak dapat dikirim sampai terhubung kembali.</div>`;\n    const dir=m.dir||'in';\n    const sender=isGroup&&dir==='in'&&m.sender?`<div class=\"sender\"><span class=\"av\" style=\"background:${randColor(m.sender)}\">${m.sender[0]}</span><span class=\"nm\">${m.sender}</span><span class=\"ty\">${m.senderType||''}</span></div>`:'';\n    const mention=m.mention?'<span class=\"at\">@Dany</span> ':'';\n    // Reply quote\n    const quote=m.replyTo?`<div class=\"reply-quote\"><span class=\"rq-name\">${m.replyTo.name}</span><span class=\"rq-text\">${m.replyTo.text}</span></div>`:'';\n    // Attachment: image / file\n    let body=m.text||'';\n    if(m.image)body=`<div class=\"msg-image\">🖼️ <span>${m.image}</span></div>`+(m.text?`<div style=\"margin-top:4px\">${m.text}</div>`:'');\n    else if(m.file)body=`<div class=\"msg-file\">📎 <span class=\"fn\">${m.file}</span><span class=\"fs\">${m.fileSize||''}</span></div>`+(m.text?`<div style=\"margin-top:4px\">${m.text}</div>`:'');\n    // Read receipt (out only)\n    const receipt=dir==='out'?`<span class=\"rcpt ${m.read?'read':''}\">${m.read?'✓✓':'✓'}</span>`:'';\n    return`<div class=\"bub ${dir}\">${sender}${quote}${mention}${body}<div class=\"t\">${m.time}${receipt}</div></div>`;\n  }).join('');\n  el.scrollTop=el.scrollHeight;\n  updCost(id);\n}\n\n// ── Send message ──\nfunction doSend(){\n  const inp=document.getElementById('composeInput');\n  const text=inp.value.trim();if(!text||!activeConvId)return;\n  const c=DB.conversations.find(x=>x.id===activeConvId);\n  // Cost guardrail (whatsapp-api only)\n  if(c&&c.channel==='whatsapp-api'){\n    const cfg=DB.costConfig||{};\n    const msgs=DB.threads[activeConvId]||[];\n    const totalBubbles=(msgs.filter(m=>m.dir==='out').length+msgs.filter(m=>m.dir==='in').length+1); // +1 for this message\n    const costEst=totalBubbles*358;\n    if(cfg.blockOnExceed&&cfg.capPerChat>0&&costEst>cfg.capPerChat){\n      showToast('🚫 Batas biaya percakapan tercapai. Pesan tidak dapat dikirim.');\n      return;\n    }\n  }\n  const time=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});\n  if(!DB.threads[activeConvId])DB.threads[activeConvId]=[];\n  DB.threads[activeConvId].push({id:genId('m'),from:'u1',text,time,dir:'out'});\n  dbUpdate('conversations',activeConvId,{lastMsg:text,lastTime:new Date().toISOString()});\n  inp.value='';\n  renderThread(activeConvId);\n  renderConvList();\n}\n\nfunction closeConv(){\n  if(!activeConvId)return;\n  document.getElementById('resolveModal').classList.add('open');\n}\nfunction doCloseConv(){\n  document.getElementById('resolveModal').classList.remove('open');\n  if(!activeConvId)return;\n  dbUpdate('conversations',activeConvId,{status:'closed'});\n  showToast('Percakapan ditutup');\n  renderConvList();\n}\n\n// ── Reconnect channel modal (2 conditions) ──\nfunction openReconnectModal(){\n  if(!activeConvId)return;\n  const c=DB.conversations.find(x=>x.id===activeConvId);if(!c)return;\n  const ch=DB.channels.find(x=>x.id===c.channel);if(!ch)return;\n  const teamId=c.teamId;\n  // Find available (active) channels of same platform in this team\n  const available=(DB.teamChannels||[]).filter(tc=>tc.teamId===teamId&&tc.platform===c.channel&&tc.status==='active');\n  const title=document.getElementById('rcTitle');\n  const body=document.getElementById('rcBody');\n  title.textContent='⟳ Hubungkan Kembali — '+ch.title;\n  if(available.length>0){\n    // Condition 1: team has replacement channel → select dropdown\n    body.innerHTML=`<p style=\"font-size:13px;color:var(--muted);margin-bottom:14px\">Tim sudah mengganti akun channel. Pilih akun baru untuk percakapan ini.</p>\n      <label style=\"font-size:12px;font-weight:600;display:block;margin-bottom:6px\">Akun Channel Tersedia</label>\n      <div id=\"rcChannelList\">${available.map(tc=>`<label style=\"display:flex;align-items:center;gap:10px;padding:10px;border:1px solid var(--border);border-radius:8px;cursor:pointer;margin-bottom:6px\" onclick=\"this.querySelector('input').checked=true;document.querySelectorAll('#rcChannelList label').forEach(l=>l.style.borderColor='var(--border)');this.style.borderColor='var(--accent)'\"><input type=\"radio\" name=\"rcChannel\" value=\"${tc.id}\" style=\"accent-color:var(--accent)\"><div><div style=\"font-weight:600;font-size:13px\">${tc.name}</div><div style=\"font-size:11px;color:var(--muted)\">${tc.phone}</div></div></label>`).join('')}</div>\n      <div class=\"modal-actions\" style=\"margin-top:14px\"><button class=\"btn\" onclick=\"document.getElementById('reconnectModal').classList.remove('open')\">Batal</button><button class=\"btn primary\" onclick=\"doReconnectSelect()\">Hubungkan</button></div>`;\n  } else {\n    // Condition 2: no replacement → scan QR (WhatsApp Web) or redirect to settings\n    const isWA=c.channel.startsWith('whatsapp');\n    body.innerHTML=isWA\n      ?`<p style=\"font-size:13px;color:var(--muted);margin-bottom:14px\">Tim belum mengganti akun. Scan QR untuk menghubungkan kembali nomor WhatsApp.</p>\n        <div style=\"display:flex;flex-direction:column;align-items:center;gap:12px;padding:14px;border:1px solid var(--border);border-radius:10px;background:var(--bg)\">\n          <div style=\"width:200px;height:200px;border:2px dashed var(--border);border-radius:10px;display:grid;place-items:center;font-size:48px;color:var(--muted)\">📷</div>\n          <p style=\"font-size:12px;color:var(--muted)\">Buka WhatsApp di ponsel → Pengaturan → Perangkat tertaut → Pindai kode QR</p>\n        </div>\n        <div class=\"modal-actions\" style=\"margin-top:14px\"><button class=\"btn\" onclick=\"document.getElementById('reconnectModal').classList.remove('open')\">Batal</button><button class=\"btn primary\" onclick=\"doReconnectQR()\">⟳ Muat Ulang QR</button></div>`\n      :`<p style=\"font-size:13px;color:var(--muted);margin-bottom:14px\">Tim belum mengganti akun. Silakan atur ulang akun channel di halaman pengaturan.</p>\n        <div class=\"modal-actions\" style=\"margin-top:14px\"><button class=\"btn\" onclick=\"document.getElementById('reconnectModal').classList.remove('open')\">Batal</button><button class=\"btn primary\" onclick=\"showToast('Mengarahkan ke pengaturan…');document.getElementById('reconnectModal').classList.remove('open')\">⚙ Buka Pengaturan</button></div>`;\n  }\n  document.getElementById('reconnectModal').classList.add('open');\n}\nfunction doReconnectSelect(){\n  const sel=document.querySelector('input[name=rcChannel]:checked');\n  if(!sel){showToast('Pilih akun channel terlebih dahulu');return;}\n  const tc=(DB.teamChannels||[]).find(x=>x.id===sel.value);\n  document.getElementById('reconnectModal').classList.remove('open');\n  showToast('Channel berhasil dihubungkan kembali melalui: '+(tc?tc.name:'akun baru'));\n  // ponytail: reconnect is prototype simulation — don't persist, reload resets to disconnected\n}\nfunction doReconnectQR(){\n  showToast('Memuat ulang QR code…');\n  setTimeout(()=>{\n    document.getElementById('reconnectModal').classList.remove('open');\n    showToast('QR berhasil discan — channel terhubung kembali');\n    // ponytail: prototype simulation — reload resets to disconnected\n  },2000);\n}\n\n// ── Drawer ──\nfunction toggleDrawer(){\n  const isFloat=layout().classList.contains('drawerFloat');\n  const drawer=document.getElementById('convDrawer');\n  if(isFloat){\n    drawerOpen=!drawerOpen;\n    drawer.style.display=''; // clear inline so CSS .open controls\n    drawer.classList.toggle('open',drawerOpen);\n    const sc=document.getElementById('drawerScrim');if(sc)sc.classList.toggle('on',drawerOpen);\n    updateCloseBtn(drawerOpen);\n  } else {\n    drawer.classList.remove('open'); // clear .open so inline style controls\n    detailOpen=!detailOpen;\n    drawer.style.display=detailOpen?'block':'none';\n    updateCloseBtn(detailOpen);\n  }\n}\nfunction updateCloseBtn(detailVisible){\n  const btnInline=document.getElementById('btnCloseConv');\n  const btnDrawer=document.getElementById('drawerCloseConv');\n  if(btnInline)btnInline.style.display=detailVisible?'none':'';\n  if(btnDrawer){\n    btnDrawer.style.display=detailVisible?'block':'none';\n    if(detailVisible){btnDrawer.style.position='sticky';btnDrawer.style.bottom='0';btnDrawer.style.margin='12px 15px';btnDrawer.style.width='calc(100% - 30px)';btnDrawer.style.zIndex='3';}\n  }\n}\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'){if(drawerOpen||detailOpen)toggleDrawer();}});\n\nfunction dsec(title,badge,inner){\n  const b=badge!=null?`<span class=\"dbadge\">${badge}</span>`:'';\n  return `<details class=\"dsec\" open><summary>${title}${b}<span class=\"chev\">▾</span></summary><div class=\"dsec-body\">${inner}</div></details>`;\n}\nfunction seeAll(){return `<a class=\"see-all\" onclick=\"showToast('Prototype: buka daftar lengkap')\">Lihat semua ›</a>`;}\n\nfunction renderDrawer(c,ct){\n  const d=(DB.convDetail||{})[c.id]||{};\n  const team=DB.teams?DB.teams.find(t=>t.id===c.teamId):null;\n  const assignees=(c.assignees||[c.assignee].filter(Boolean)).map(aid=>{const a=DB.agents.find(x=>x.id===aid);return a?a.name:null}).filter(Boolean);\n  const msgs=DB.threads[c.id]||[];\n  const outCount=msgs.filter(m=>m.dir==='out').length;\n  const inCount=msgs.filter(m=>m.dir==='in').length;\n  const pill=t=>`<span class=\"dpill\">${t}</span>`;\n  const row=(k,v)=>`<div class=\"drow\"><span class=\"dk\">${k}</span><span class=\"dv\">${v}</span></div>`;\n  let h='';\n\n  // ── Section order: old proto ──\n  // 1. Customer\n  if(ct){\n    const ch=DB.channels.find(x=>x.id===c.channel);\n    const chPill=ch?`${ch.icon} ${ch.title}`:c.channel;\n    const statusPill=`<span class=\"dpill\" style=\"background:#d1fae5;color:#065f46\">${chPill} · Open</span>`;\n    const labels=(d.clientTags||[]).map(pill).join('')+'<span class=\"dadd\" onclick=\"openLabelModal()\">＋</span>';\n    h+=dsec('Customer',null,\n      `<div style=\"font-weight:600;font-size:14px\">${ct.name}</div>`+\n      `<div class=\"drow\"><span class=\"dv\">${ct.phone} <button class=\"dlink\" style=\"font-size:10px\" onclick=\"showToast('Disalin')\">⧉</button></span></div>`+\n      `<div style=\"margin:6px 0\">${statusPill}</div>`+\n      `<div class=\"dtags\">${labels}</div>`+\n      `<button class=\"dlink\" style=\"margin:8px 0;font-size:11px;color:var(--primary)\" onclick=\"openProspekModal()\">＋ Buat Prospek</button>`);\n  }\n\n  // 2. Simulasi Biaya (whatsapp-api only)\n  if(c.channel==='whatsapp-api'){\n    const totalCount=inCount+outCount;\n    const costEst=totalCount*358;\n    const cfg=DB.costConfig||{};\n    h+=dsec('Simulasi Biaya',null,\n      row('Bubble masuk (inbound)',inCount)+row('Bubble keluar (outbound)',outCount)+row('Total bubble',totalCount)+row('Tarif / bubble','Rp 358')+\n      `<div class=\"drow\"><span class=\"dk\" style=\"font-weight:700\">Total estimasi</span><span class=\"dv\" style=\"font-weight:700\">${fmtRupiah(costEst)}</span></div>`+\n      (cfg.capPerChat>0?`<div class=\"drow\"><span class=\"dk\">Cap bulanan</span><span class=\"dv\">${fmtRupiah(cfg.capPerChat)}</span></div>`:''));\n    // Alert banner when exceeding cap\n    if(cfg.alertEnabled&&cfg.capPerChat>0&&costEst>cfg.capPerChat){\n      h+=`<div style=\"margin:8px 14px;padding:10px 14px;border-radius:8px;background:#fef3c7;border:1px solid #fde68a;font-size:12px;color:#92400e;font-weight:600\">⚠️ Biaya percakapan (${fmtRupiah(costEst)}) melebihi batas (${fmtRupiah(cfg.capPerChat)})</div>`;\n    }\n    // Block banner when blockOnExceed\n    if(cfg.blockOnExceed&&cfg.capPerChat>0&&costEst>cfg.capPerChat){\n      h+=`<div style=\"margin:8px 14px;padding:10px 14px;border-radius:8px;background:#fef2f2;border:1px solid #fecaca;font-size:12px;color:#991b1b;font-weight:600\">🚫 Batas biaya tercapai. Pesan tidak dapat dikirim. Kirim template pesan untuk melanjutkan.</div>`;\n    }\n  }\n\n  // 3. Assignment\n  h+=dsec('Assignment',null,\n    row('Kotak Masuk (Tim)', team?`${team.icon} ${team.title}`:'<a class=\"dlink\">＋ Tetapkan Tim</a>')+\n    row('Penerima (Agen)', assignees.length?assignees.join(', '):'<a class=\"dlink\" onclick=\"openAssignModal()\">＋ Tetapkan Agen</a>')+\n    row('Sumber',d.source||'self-pull'));\n\n  // 4. SLA\n  if(d.sla){\n    const s=d.sla;\n    const slaRow=(lbl,val,state,label,tip)=>`<div class=\"drow\"><span class=\"dk\">${lbl}</span><span class=\"dv\" style=\"font-weight:600\">${val}</span><span class=\"dpill\" style=\"font-size:10px;${state==='warn'?'background:#fef3c7;color:#92400e':state==='breach'?'background:#fecaca;color:#991b1b':'background:#d1fae5;color:#065f46'}\">${label}</span><span style=\"font-size:10px;color:var(--muted);cursor:help\" title=\"${tip}\">ⓘ</span></div>`;\n    h+=dsec('SLA',null,\n      slaRow('FRT',s.frt.val,s.frt.state,s.frt.label,'First Response Time — waktu agent pertama merespons. SLA: 15 menit.')+\n      slaRow('TTC',s.ttc.val,s.ttc.state,s.ttc.label,'Time To Close — hingga percakapan selesai. SLA: 4 jam.')+\n      slaRow('RLT',s.rlt.val,s.rlt.state,s.rlt.label,'Resolution Time — waktu penyelesaian. SLA: 2 jam.')+\n      slaRow('Wait',s.wait.val,s.wait.state,s.wait.label,'Wait time in queue (FE v2.8.0).'));\n  }\n\n  // 5. Tiket\n  const tks=DB.tickets.filter(t=>t.contactId===c.contactId);\n  h+=dsec('Tiket',tks.length||null,\n    tks.length?tks.map(t=>`<div class=\"dcard\"><div class=\"dcard-t\">🎫 ${t.subject}</div><div class=\"dcard-s\">status: <span class=\"dpill\">${t.status}</span></div></div>`).join('')+seeAll():row('Status','Belum ada tiket'));\n\n  // 6. Metadata\n  h+=dsec('Metadata',null,\n    row('Sumber',(DB.channels.find(x=>x.id===c.channel)||{}).title||c.channel)+\n    row('Akun',d.accountConnected||'-')+\n    row('Dibuat',new Date(c.lastTime||ct&&ct.lastActive||Date.now()).toLocaleString('id-ID',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' WIB')+\n    row('OS',ct&&ct.os||'-')+row('Browser',ct&&ct.browser||'-'));\n\n  // 7. Custom Attributes (new proto extra)\n  if(d.customAttrs)h+=dsec('Atribut Kustom',null,\n    d.customAttrs.map(a=>row(a.k,a.v)).join('')+seeAll());\n\n  // 8. Histori\n  if(d.history)h+=dsec('Histori',d.historyTotal||d.history.length,\n    d.history.map(x=>`<div class=\"dhist\"><span class=\"av\">${x.name.split(' ').map(w=>w[0]).join('').slice(0,2)}</span><div><b>${x.name}</b><div class=\"dhist-t\">${x.time}</div><div class=\"dhist-p\">${x.preview}</div></div></div>`).join('')+seeAll());\n\n  // 9. Catatan\n  if(d.notes)h+=dsec('Catatan',d.notesTotal||d.notes.length,\n    `<input class=\"dnote-in\" placeholder=\"Tambah catatan…\">`+\n    d.notes.map((n,i)=>`<div class=\"dnote ${i===0?'hl':''}\"><span class=\"pin\">📌</span><div><b>${n.by}</b> ${n.text}</div></div>`).join('')+seeAll());\n\n  // 10. Log (Events)\n  if(d.events)h+=dsec('Log',d.eventsTotal||d.events.length,\n    `<div class=\"dtl\">${d.events.map(e=>`<div class=\"dtl-i\"><span class=\"dot ${e.dot||''}\"></span><div><div class=\"dtl-t\">${e.t}</div><div class=\"dtl-x\">${e.text}</div></div></div>`).join('')}</div>`+seeAll());\n\n  // ── Extra sections (new proto) ──\n  if(d.pinned)h+=dsec('Pesan Disematkan',d.pinnedTotal||d.pinned.length,\n    d.pinned.map(p=>`<div class=\"dpin\"><span class=\"pin\">📌</span><div><b>dari ${p.from}</b><div class=\"dpin-b\">${p.text}</div><div class=\"dpin-m\">disematkan oleh ${p.pinnedBy}</div></div></div>`).join('')+seeAll());\n  if(d.media)h+=dsec('Media',d.mediaTotal||d.media.length,\n    `<div class=\"dgrid\">${d.media.map(m=>`<div class=\"dthumb\">${m}</div>`).join('')}</div>`+seeAll());\n  if(d.files)h+=dsec('Berkas',d.filesTotal||d.files.length,\n    d.files.map(f=>`<div class=\"dfile\"><span class=\"fext ${f.ext}\">${f.ext.toUpperCase()}</span><div><div class=\"dfile-n\">${f.name}</div><div class=\"dfile-m\">${f.by} · ${f.size} · ${f.ext}</div></div></div>`).join('')+seeAll());\n\n  if(!c.isGroup) h+=`<button class=\"btn danger\" id=\"drawerCloseConv\" onclick=\"closeConv()\">Tutup Percakapan</button>`;\n\n  document.getElementById('drawerBody').innerHTML=h;\n}\n\nfunction updCost(id){\n  const el=document.getElementById('drawerCost');\n  if(!el)return; // drawer belum ke-render\n  const count=(DB.threads[id]||[]).filter(m=>m.dir==='out').length;\n  el.textContent=`Bubble: ${count} × Rp 358 = ${fmtRupiah(count*358)}`;\n}\n\nfunction filterConvList(){renderConvList()}\n\n// ── Label modal ──\nconst LABELS=['VIP','Prioritas','Follow-up','Komplain','Spam','Retur','Merchant','Pelanggan','Urgent'];\nfunction openLabelModal(){\n  if(!activeConvId)return;\n  const d=(DB.convDetail||{})[activeConvId]||{};\n  const cur=d.clientTags||[];\n  renderLabelList(cur,'');\n  document.getElementById('labelSearch').value='';\n  document.getElementById('labelCreate').style.display='none';\n  document.getElementById('labelModal').classList.add('open');\n}\nfunction renderLabelList(cur,filter){\n  const el=document.getElementById('labelList');\n  const q=filter.toLowerCase();\n  const all=[...new Set([...LABELS,...cur])];\n  const filtered=q?all.filter(l=>l.toLowerCase().includes(q)):all;\n  el.innerHTML=filtered.map(l=>{\n    const active=cur.includes(l);\n    return`<div style=\"display:flex;align-items:center;gap:10px;padding:8px 10px;cursor:pointer;border-radius:6px;${active?'background:var(--accent-light,#dbeafe)':''}\" onclick=\"toggleLabel('${l}')\">\n      <span style=\"font-size:16px\">${active?'☑':'☐'}</span>\n      <span style=\"font-size:13px\">${l}</span>\n      ${active?'<span style=\"margin-left:auto;font-size:10px;color:var(--primary)\">✓</span>':''}\n    </div>`;\n  }).join('');\n  document.getElementById('labelCreate').style.display=q&&!all.includes(q)?'block':'none';\n}\nfunction filterLabels(q){\n  const d=(DB.convDetail||{})[activeConvId]||{};\n  renderLabelList(d.clientTags||[],q);\n}\nfunction toggleLabel(label){\n  if(!activeConvId)return;\n  if(!DB.convDetail)DB.convDetail={};\n  if(!DB.convDetail[activeConvId])DB.convDetail[activeConvId]={};\n  const d=DB.convDetail[activeConvId];\n  if(!d.clientTags)d.clientTags=[];\n  const i=d.clientTags.indexOf(label);\n  if(i>=0)d.clientTags.splice(i,1); else d.clientTags.push(label);\n  saveStore();\n  renderLabelList(d.clientTags,document.getElementById('labelSearch').value);\n  renderDrawer(DB.conversations.find(x=>x.id===activeConvId),DB.contacts.find(x=>x.id===(DB.conversations.find(x=>x.id===activeConvId)||{}).contactId));\n}\nfunction createLabel(){\n  const q=document.getElementById('labelSearch').value.trim();\n  if(!q)return;\n  LABELS.push(q);\n  toggleLabel(q);\n  document.getElementById('labelSearch').value='';\n  document.getElementById('labelCreate').style.display='none';\n}\n\n// ── Prospek (Lead) modal — fields from FE AddLeadModal.tsx ──\nfunction openProspekModal(){\n  if(!activeConvId)return;\n  const c=DB.conversations.find(x=>x.id===activeConvId);if(!c)return;\n  const ct=DB.contacts.find(x=>x.id===c.contactId)||{};\n  // Populate selects\n  const teamSel=document.getElementById('pTeam');\n  teamSel.innerHTML='<option value=\"\">Pilih kotak tim</option>'+DB.teams.map(t=>`<option value=\"${t.id}\" ${t.id===c.teamId?'selected':''}>${t.icon} ${t.title}</option>`).join('');\n  const agentSel=document.getElementById('pAssignee');\n  agentSel.innerHTML='<option value=\"\">Pilih agen</option>'+DB.agents.map(a=>`<option value=\"${a.id}\" ${a.id===c.assignee?'selected':''}>${a.name}</option>`).join('');\n  const chSel=document.getElementById('pChannel');\n  chSel.innerHTML='<option value=\"\">Pilih channel</option>'+DB.channels.filter(ch=>ch.connected!==false).map(ch=>`<option value=\"${ch.id}\" ${ch.id===c.channel?'selected':''}>${ch.icon} ${ch.title}</option>`).join('');\n  // Pre-fill from contact\n  document.getElementById('pTitle').value=ct.name?`Prospek — ${ct.name}`:'';\n  document.getElementById('pContactValue').value=ct.phone||'';\n  document.getElementById('pName').value=ct.name||'';\n  document.getElementById('pOffice').value='';\n  document.getElementById('pJobTitle').value='';\n  document.getElementById('pEmail').value=ct.email||'';\n  document.getElementById('pOfficePhone').value='';\n  document.getElementById('pBusinessType').value='';\n  document.getElementById('pAddress').value=ct.location||'';\n  document.getElementById('prospekModal').classList.add('open');\n}\nfunction doCreateProspek(){\n  const title=document.getElementById('pTitle').value.trim();\n  const team=document.getElementById('pTeam').value;\n  const name=document.getElementById('pName').value.trim();\n  if(!title||!team||!name){showToast('Lengkapi field wajib (*): Judul, Tim, Nama Kontak');return;}\n  document.getElementById('prospekModal').classList.remove('open');\n  showToast('Prospek berhasil dibuat: '+title);\n}\n\n// ponytail: contact search — filter DB.contacts by name prefix, auto-fill phone/email on match\nfunction onProspekContactSearch(q){\n  const dl=document.getElementById('dlContacts');\n  const matchEl=document.getElementById('pContactMatch');\n  dl.innerHTML='';\n  if(q.length<2){matchEl.textContent='';return;}\n  const hits=DB.contacts.filter(c=>c.name.toLowerCase().includes(q.toLowerCase())).slice(0,8);\n  hits.forEach(c=>{const o=document.createElement('option');o.value=c.name;dl.appendChild(o);});\n  // Auto-fill if exact match\n  const exact=hits.find(c=>c.name.toLowerCase()===q.toLowerCase());\n  if(exact){\n    document.getElementById('pContactValue').value=exact.phone||'';\n    document.getElementById('pEmail').value=exact.email||'';\n    document.getElementById('pAddress').value=exact.location||'';\n    matchEl.textContent='✓ Kontak ditemukan — '+exact.phone;\n  } else {\n    matchEl.textContent=hits.length?hits.length+' kontak ditemukan':'Tidak ada match';\n  }\n}\n\n// ── Template message modal (WA API 24h expired) ──\nlet selectedTpl=null;\nfunction openTemplateModal(){\n  const tpls=(DB.templates||[]).filter(t=>t.status==='APPROVED');\n  renderTemplateList(tpls);\n  document.getElementById('tplSearch').value='';\n  document.getElementById('templateModal').classList.add('open');\n}\nfunction renderTemplateList(tpls){\n  const catColors={UTILITY:'#dbeafe',MARKETING:'#fce7f3',AUTHENTICATION:'#d1fae5'};\n  const el=document.getElementById('tplList');\n  el.innerHTML=tpls.map(t=>{\n    const bg=catColors[t.category]||'#f3f4f6';\n    const btns=t.buttons||[];\n    const btnCount=btns.length;\n    return`<div style=\"padding:12px;border:1px solid var(--border);border-radius:10px;cursor:pointer;transition:border-color .15s\" onclick=\"previewTemplate('${t.id}')\" onmouseenter=\"this.style.borderColor='var(--accent)'\" onmouseleave=\"this.style.borderColor='var(--border)'\">\n      <div style=\"display:flex;align-items:center;gap:8px;margin-bottom:6px\">\n        <span style=\"font-size:11px;font-weight:600;padding:2px 8px;border-radius:6px;background:${bg};color:var(--fg)\">${t.category}</span>\n        <span style=\"font-size:12px;font-weight:600\">${t.name}</span>\n        <span style=\"font-size:10px;color:var(--muted);margin-left:auto\">${t.language}</span>\n      </div>\n      <div style=\"font-size:12px;color:var(--muted);line-height:1.4;max-height:40px;overflow:hidden\">${t.body}</div>\n      ${btnCount?`<div style=\"margin-top:6px;font-size:10px;color:var(--muted)\">🔘 ${btnCount} tombol</div>`:''}\n    </div>`;\n  }).join('')||'<div style=\"text-align:center;color:var(--muted);padding:20px\">Tidak ada template aktif</div>';\n}\nfunction filterTemplates(q){\n  const tpls=(DB.templates||[]).filter(t=>t.status==='APPROVED');\n  const filtered=q?tpls.filter(t=>t.name.toLowerCase().includes(q.toLowerCase())||t.body.toLowerCase().includes(q.toLowerCase())):tpls;\n  renderTemplateList(filtered);\n}\nfunction previewTemplate(id){\n  selectedTpl=(DB.templates||[]).find(t=>t.id===id);\n  if(!selectedTpl)return;\n  document.getElementById('templateModal').classList.remove('open');\n  document.getElementById('tplPreviewTitle').textContent='📋 '+selectedTpl.name;\n  // Render body with {{n}} as highlighted placeholders\n  let body=selectedTpl.body.replace(/\\{\\{(\\d+)\\}\\}/g,'<span style=\"background:#fef3c7;padding:1px 4px;border-radius:4px;font-weight:600\">{{$1}}</span>');\n  document.getElementById('tplPreviewBody').innerHTML=body;\n  const btns=selectedTpl.buttons||[];\n  document.getElementById('tplPreviewButtons').innerHTML=btns.map(b=>{\n    const style=b.type==='URL'?'background:var(--primary);color:#fff':'background:var(--bg);border:1px solid var(--border)';\n    return`<span style=\"padding:6px 12px;border-radius:8px;font-size:11px;font-weight:600;${style}\">${b.text}</span>`;\n  }).join('');\n  document.getElementById('tplPreviewModal').classList.add('open');\n}\nfunction sendTemplate(){\n  if(!selectedTpl||!activeConvId)return;\n  // Simulate sending template as outgoing message\n  if(!DB.threads[activeConvId])DB.threads[activeConvId]=[];\n  const time=new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});\n  DB.threads[activeConvId].push({id:genId('m'),from:'u1',text:'[Template] '+selectedTpl.name+'\\n'+selectedTpl.body,time,dir:'out'});\n  dbUpdate('conversations',activeConvId,{lastMsg:'[Template] '+selectedTpl.name,lastTime:new Date().toISOString()});\n  document.getElementById('tplPreviewModal').classList.remove('open');\n  renderThread(activeConvId);\n  renderConvList();\n  showToast('Template \"'+selectedTpl.name+'\" berhasil dikirim');\n  selectedTpl=null;\n}\n\nfunction randColor(s){const colors=['#4f46e5','#0891b2','#dc2626','#16a34a','#9333ea','#ea580c','#2563eb'];let h=0;for(let i=0;i<s.length;i++)h=s.charCodeAt(i)+((h<<5)-h);return colors[Math.abs(h)%colors.length]}\n\n// ── Assign agent + max conversation guard ──\nlet cmPendingAgentId=null;\nfunction closeModal(id){const e=document.getElementById(id);if(e){e.classList.remove('show');e.classList.remove('open');e.classList.add('hide')}}\n\nfunction openAssignModal(){\n  const list=document.getElementById('assignAgentList');\n  list.innerHTML=DB.agents.map(a=>{\n    const full=(a.currentConv||0)>=(a.maxConv||10);\n    return`<div style=\"display:flex;align-items:center;gap:10px;padding:10px;cursor:pointer;border-bottom:1px solid var(--border);${full?'opacity:0.6':''}\" onclick=\"tryAssignAgent('${a.id}')\">\n      <span style=\"width:32px;height:32px;border-radius:50%;background:${a.color||'#4f46e5'};color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600\">${a.initials||a.name[0]}</span>\n      <div style=\"flex:1\"><div style=\"font-weight:500;font-size:13px\">${a.name}</div><div style=\"font-size:11px;color:var(--muted)\">${a.currentConv||0}/${a.maxConv||10} percakapan</div></div>\n      ${full?'<span style=\"font-size:11px;color:#ef4444;font-weight:600\">PENUH</span>':'<span style=\"font-size:11px;color:var(--primary)\">Pilih</span>'}\n    </div>`;\n  }).join('');\n  document.getElementById('assignModal').classList.add('open');\n}\n\nfunction tryAssignAgent(aid){\n  const a=DB.agents.find(x=>x.id===aid);\n  if(!a)return;\n  if((a.currentConv||0)>=(a.maxConv||10)){\n    cmPendingAgentId=aid;\n    document.getElementById('cmAgentInfo').textContent=`Agen ${a.name} sudah mencapai batas maksimum percakapan (${a.maxConv||10}). Silakan ubah batas untuk menetapkan.`;\n    document.getElementById('cmCurrent').value=a.maxConv||10;\n    document.getElementById('cmInput').value='';\n    document.getElementById('cmSubmit').disabled=true;\n    closeModal('assignModal');\n    document.getElementById('changeMaxModal').classList.add('open');\n  } else {\n    doAssign(aid);\n  }\n}\n\nfunction cmValidate(){\n  const v=document.getElementById('cmInput').value;\n  document.getElementById('cmSubmit').disabled=!(v!==''&&/^\\d+$/.test(v)&&parseInt(v,10)>0);\n}\n\nfunction saveMaxAndAssign(){\n  const a=DB.agents.find(x=>x.id===cmPendingAgentId);\n  if(!a)return;\n  a.maxConv=parseInt(document.getElementById('cmInput').value,10);\n  dbUpdate('agents',a.id,a);\n  closeModal('changeMaxModal');\n  doAssign(cmPendingAgentId);\n  cmPendingAgentId=null;\n}\n\nfunction doAssign(aid){\n  if(!activeConvId)return;\n  const c=DB.conversations.find(x=>x.id===activeConvId);\n  if(!c)return;\n  if(!c.assignees)c.assignees=c.assignee?[c.assignee]:[];\n  if(!c.assignees.includes(aid)){\n    c.assignees.push(aid);\n    const a=DB.agents.find(x=>x.id===aid);\n    if(a){a.currentConv=(a.currentConv||0)+1;dbUpdate('agents',a.id,a)}\n    dbUpdate('conversations',c.id,c);\n  }\n  renderDrawer(c,DB.contacts.find(ct=>ct.id===c.contactId));\n  closeModal('assignModal');\n}\n\n// ── Modal helpers ──\nfunction openModal(id){\n  const m=document.getElementById(id);if(m)m.classList.remove('hide');\n  if(id==='m-advanced')initAdvFilter();\n}\n// closeModal already defined above\n\n// ── Visibilitas toggles ──\nconst visState={waBadge:true,tags:true};\nfunction toggleVis(key,on){\n  visState[key]=on;\n  const sw=event?.target?.closest?.('.switch');\n  if(sw)sw.classList.toggle('on',on);\n  renderConvList();\n}\n\n// ── Advanced filter (agents + tags) ──\nlet advAgents=[], advTags=[];\nfunction initAdvFilter(){\n  // Agent checkboxes\n  const al=document.getElementById('advAgentList');\n  if(al)al.innerHTML=DB.agents.map(a=>`<label style=\"display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;border-bottom:1px solid var(--border);font-size:13px\"><input type=\"checkbox\" value=\"${a.id}\" ${advAgents.includes(a.id)?'checked':''} onchange=\"toggleAdvAgent('${a.id}',this.checked)\"> ${a.name}</label>`).join('');\n  // Tag pills\n  const allTags=[...new Set(DB.contacts.flatMap(c=>c.tags||[]))];\n  const tl=document.getElementById('advTagList');\n  if(tl)tl.innerHTML=allTags.map(t=>`<span class=\"badge-pill\" style=\"cursor:pointer;${advTags.includes(t)?'background:var(--accent);color:#fff':''}\" onclick=\"toggleAdvTag('${t}',this)\">${t}</span>`).join('');\n  renderAdvBadges();\n}\nfunction toggleAdvAgent(id,on){\n  if(on&&!advAgents.includes(id))advAgents.push(id);\n  else if(!on)advAgents=advAgents.filter(a=>a!==id);\n}\nfunction toggleAdvTag(tag,el){\n  if(advTags.includes(tag)){advTags=advTags.filter(t=>t!==tag);el.style.background='';el.style.color=''}\n  else{advTags.push(tag);el.style.background='var(--accent)';el.style.color='#fff'}\n  renderAdvBadges();\n}\nfunction renderAdvBadges(){\n  const sa=document.getElementById('selected-agents');\n  if(sa)sa.innerHTML=advAgents.map(id=>{const a=DB.agents.find(x=>x.id===id);return a?`<span class=\"badge-pill\">${a.name} <span onclick=\"advAgents=advAgents.filter(x=>x!=='${id}');initAdvFilter();renderConvList()\" style=\"cursor:pointer;margin-left:4px\">&times;</span></span>`:''}).join('');\n  const st=document.getElementById('selected-tags');\n  if(st)st.innerHTML=advTags.map(t=>`<span class=\"badge-pill\">${t} <span onclick=\"advTags=advTags.filter(x=>x!=='${t}');initAdvFilter();renderConvList()\" style=\"cursor:pointer;margin-left:4px\">&times;</span></span>`).join('');\n}\nfunction resetAdvFilter(){advAgents=[];advTags=[];initAdvFilter();renderConvList()}\nfunction applyAdvFilter(){renderConvList()}\n\n// ── Init ──\nrenderSideSections();\nsetVp(window.innerWidth);\nrenderConvList();\nfillBulkDropdowns();\n</script>\n";
